window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[105]={"id":"105","numero":105,"titre":"Item 105 — Épilepsies de l'enfant et de l'adulte","objectifs":[{"id":"105-1","rang":"A","rubrique":"Définition","titre":"Définir la crise d'épilepsie et la maladie épileptique","contenu":"<p><span class=\"kw-def\">Crise d'épilepsie</span> = <b>manifestation clinique paroxystique</b> (<span class=\"kw-clinique\">motrice, sensitive, sensorielle, végétative ou psychique</span>) liée à une <span class=\"kw-def\">décharge anormale, excessive et hypersynchrone d'une population neuronale corticale</span>. La sémiologie reflète la topographie de la décharge — souvent <span class=\"kw-clinique\">stéréotypée chez un même malade</span>.</p>\n\n      <p><span class=\"kw-def\">Maladie épileptique</span> = <b>prédisposition cérébrale durable à générer des crises</b>. Le diagnostic est posé devant l'un des 3 critères <span class=\"kw-def\">ILAE</span> :</p>\n\n      <table >\n        <thead><tr><th>Critère</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td><b><span class=\"kw-chiffre\">≥ 2 crises non provoquées</span></b></td><td>Espacées de <span class=\"kw-chiffre\">≥ 24 h</span>, cliniquement avérées.</td></tr>\n          <tr><td><b>1 seule crise + risque récidive <span class=\"kw-chiffre\">&gt; 60 % à 10 ans</span></b></td><td>Soit <span class=\"kw-chiffre\">≥ 1</span> élément pathologique : <strong><span class=\"kw-bio\">EEG</span> :</strong> anomalies paroxystiques ; <br><strong><span class=\"kw-imagerie\">Imagerie</span> :</strong> <span class=\"kw-radio\">lésion épileptogène préexistante</span> ; <br><strong>Développement :</strong> <span class=\"kw-clinique\">trouble neurodéveloppemental</span> préexistant.</td></tr>\n          <tr><td><b><span class=\"kw-def\">Syndrome épileptique</span> identifié</b></td><td>Selon la <span class=\"kw-def\">classification</span> <span class=\"kw-def\">ILAE</span> (cf. obj-2).</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Piège classique.</strong> Une <span class=\"kw-clinique\">crise unique non provoquée</span> sans <span class=\"kw-def\">critère de</span> prédisposition durable n'autorise PAS le diagnostic de maladie épileptique. À l'inverse, <span class=\"kw-chiffre\">2 crises provoquées</span> (<span class=\"kw-etio\">sevrage OH</span>, <span class=\"kw-bio\">hypoglycémie</span>…) ne définissent pas non plus une <span class=\"kw-def\">épilepsie</span> : ce sont des <span class=\"kw-def\">crises symptomatiques aiguës</span>.\n      </div>","frequence":1},{"id":"105-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition d'un état de mal épileptique","contenu":"<p><span class=\"kw-def\">État de mal épileptique (EME)</span> = <span class=\"kw-def\">crise épileptique</span> <b>qui persiste suffisamment longtemps ou se répète à des intervalles suffisamment brefs</b> pour créer une <span class=\"kw-def\">condition épileptique stable et durable</span>. La <span class=\"kw-chiffre\">durée seuil</span> <span class=\"kw-clinique\">dépend du type de crise</span>.</p>\n\n      <table >\n        <thead><tr><th>Type d'EME</th><th><span class=\"kw-def\">Critère diagnostique</span> (verbatim annales)</th></tr></thead>\n        <tbody>\n          <tr><td><b><span class=\"kw-def\">EMETCG</span></b> (généralisé tonico-clonique) <span class=\"kw-alerte\">le plus fréquent & le plus grave</span></td><td><strong>Motrice :</strong> phases <span class=\"kw-clinique\">toniques + cloniques</span> durent <span class=\"kw-chiffre\">&gt; 5 min</span> ; <br><strong>Subintrante :</strong> <span class=\"kw-chiffre\">≥ 2 crises rapprochées</span> <span class=\"kw-clinique\">sans reprise de conscience intercritique</span>.</td></tr>\n          <tr><td><b><span class=\"kw-def\">EME focal</span></b></td><td>Manifestations motrices focales <span class=\"kw-chiffre\">&gt; 10-15 min</span>. <span class=\"kw-alerte\">Risque d'évolution vers EME généralisé</span>.</td></tr>\n          <tr><td><b><span class=\"kw-def\">EME larvé</span></b> (infraclinique / subtle status)</td><td><strong>Clinique :</strong> <span class=\"kw-clinique\">coma</span> persistant sans manifestation motrice (ou minimes) ; <br><strong>Mécanisme :</strong> <span class=\"kw-clinique\">dissociation électromécanique</span> ; <br><strong>Diagnostic :</strong> <span class=\"kw-bio\">EEG</span> (retard fréquent) ; <br><strong><span class=\"kw-def\">Pronostic</span> :</strong> <span class=\"kw-alerte\">aussi sévère qu'un EMETCG</span>.</td></tr>\n          <tr><td><b>Autres</b></td><td><span class=\"kw-def\">EME focal avec rupture de contact</span>, <span class=\"kw-def\">EME absence</span>, <span class=\"kw-def\">EME tonique</span>.</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Ne pas confondre EMETCG et <span class=\"kw-clinique\">coma</span> post-critique.</strong> Après une CTCG isolée, le <span class=\"kw-clinique\">coma</span> résolutif dure <span class=\"kw-clinique\">typiquement &lt; 10 min</span>, la <span class=\"kw-clinique\">confusion</span> post-critique peut persister plusieurs dizaines de minutes. Des CTCG répétées <span class=\"kw-clinique\">avec récupération de conscience entre les crises</span> ne sont PAS un EMETCG. ⚠️ <span class=\"kw-alerte\">Coma prolongé après une CTCG → évoquer un EME larvé → EEG systématique</span>.\n      </div>\n\n      <div class=\"callout callout-info\">\n        <strong>Double <span class=\"kw-alerte\">urgence</span> de l'EME.</strong> Urgence symptomatique : faire cesser la crise au plus tôt pour éviter récidive, pérennisation et séquelles neurologiques. Urgence étiologique : surtout devant un EME inaugural sans ATCD d'épilepsie connue — bilan étiologique en parallèle du traitement (cf. obj-12).\n      </div>","frequence":1},{"id":"105-3","rang":"A","rubrique":"Définition","titre":"Connaître la classification syndromique des crises d'épilepsie et son intérêt pronostique","contenu":"<p>La <span class=\"kw-def\">classification ILAE 2017</span> articule trois niveaux successifs : <b>type de crise → type d'épilepsie → syndrome épileptique</b>. Chaque niveau précise le précédent et oriente le <span class=\"kw-def\">pronostic</span> + le <span class=\"kw-ttt\">choix thérapeutique</span>.</p>\n\n      <figure class=\"ilae-schema\" aria-label=\"Schéma de la classification ILAE 2017 : trois niveaux emboîtés (type de crise, type d'épilepsie, syndrome) et axe étiologique transversal\">\n        <div class=\"ilae-levels\">\n          <div class=\"ilae-level ilae-level--1\">\n            <span class=\"ilae-level__num\">Niveau 1</span>\n            <h6 class=\"ilae-level__name\">Type de crise</h6>\n            <div class=\"ilae-level__opts\"><span>Focale</span><span>Généralisée</span><span>Inconnue</span></div>\n            <p class=\"ilae-level__note\">Focale = zone corticale circonscrite · Généralisée = deux hémisphères d'emblée · Inconnue = sémiologie / <span class=\"kw-bio\">EEG</span> insuffisants.</p>\n          </div>\n          <div class=\"ilae-level ilae-level--2\">\n            <span class=\"ilae-level__num\">Niveau 2</span>\n            <h6 class=\"ilae-level__name\">Type d'épilepsie</h6>\n            <div class=\"ilae-level__opts\"><span>Focale</span><span>Généralisée</span><span>Combinée</span><span>Inconnue</span></div>\n          </div>\n          <div class=\"ilae-level ilae-level--3\">\n            <span class=\"ilae-level__num\">Niveau 3</span>\n            <h6 class=\"ilae-level__name\">Syndrome épileptique</h6>\n            <p class=\"ilae-level__note\">Ensemble cohérent : <strong>crises + <span class=\"kw-bio\">EEG</span> + âge + <span class=\"kw-def\">comorbidités</span></strong> → conditionne le <span class=\"kw-def\">pronostic</span> et le <span class=\"kw-ttt\">traitement</span>.</p>\n          </div>\n        </div>\n        <aside class=\"ilae-etio\">\n          <span class=\"ilae-etio__label\">Axe étiologique — transversal aux 3 niveaux (cf. obj-3)</span>\n          <ul>\n            <li>Structurelle</li>\n            <li><span class=\"kw-etio\">Génétique</span></li>\n            <li>Infectieuse</li>\n            <li>Métabolique</li>\n            <li>Dysimmune</li>\n            <li>Inconnue</li>\n          </ul>\n        </aside>\n        <figcaption class=\"ilae-schema__caption\">Chaque niveau <em>précise</em> le précédent (précision croissante de gauche à droite) ; l'axe étiologique s'applique en parallèle à tous les niveaux.</figcaption>\n      </figure>\n\n      <p><span class=\"kw-def\">Intérêt pronostique</span> — le syndrome conditionne l'<span class=\"kw-def\">évolution naturelle</span> (<span class=\"kw-def\">épilepsie</span>-absence enfant pharmacosensible <span class=\"kw-chiffre\">80 %</span> <i><span class=\"kw-bio\">vs</span></i> <span class=\"kw-alerte\">syndrome de West avec régression sévère</span>), le <span class=\"kw-ttt\">choix du traitement</span> (<span class=\"kw-ttt\">valproate</span> large spectre <i>vs</i> <span class=\"kw-ttt\">carbamazépine</span> étroit), la <span class=\"kw-ttt\">durée de traitement</span> et la guidance familiale.</p>","frequence":1},{"id":"105-4","rang":"A","rubrique":"Définition","titre":"Définir une épilepsie idiopathique (génétique présumée) et connaître la classification étiologique des épilepsies","contenu":"<p><span class=\"kw-def\">Épilepsie idiopathique (génétique présumée)</span> = <span class=\"kw-def\">épilepsie</span> sans <span class=\"kw-clinique\">lésion</span> cérébrale identifiable, secondaire à une <b>prédisposition <span class=\"kw-etio\">génétique</span> présumée ou prouvée</b>. Début souvent dans l'enfance/adolescence, examen neurologique et imagerie normaux, <span class=\"kw-imagerie\">EEG</span> souvent typique du syndrome, <span class=\"kw-def\">pronostic</span> globalement favorable (pharmacosensibilité <span class=\"kw-chiffre\">≥ 70 %</span>).</p>\n\n      <p><span class=\"kw-def\">Classification étiologique ILAE 2017 — 6 catégories</span> :</p>\n\n      <table >\n        <thead><tr><th>Étiologie</th><th>Exemples</th></tr></thead>\n        <tbody>\n          <tr><td><b>Structurelle</b> <span class=\"kw-imagerie\">imagerie +</span></td><td><strong>Vasculaire :</strong> <span class=\"kw-etio\">AVC</span> <span class=\"kw-etio\">ischémique</span>/hémorragique, MAV, <span class=\"kw-etio\">cavernome</span> ; <br><strong><span class=\"kw-etio\">Tumorale</span> :</strong> <span class=\"kw-etio\">gliome bas grade</span>, méningiome, métastase ; <br><strong>Traumatique :</strong> séquelle post-TC, HSD chronique ; <br><strong>Malformative :</strong> <span class=\"kw-etio\">dysplasie corticale focale</span>, hétérotopie, <span class=\"kw-etio\">sclérose hippocampique</span>.</td></tr>\n          <tr><td><b><span class=\"kw-etio\">Génétique</span></b> (présumée ou prouvée) — <span class=\"kw-chiffre\">~40 % des épilepsies</span></td><td><strong>Canalopathies :</strong> mutations SCN1A (<span class=\"kw-etio\">syndrome de Dravet</span>), GLUT1 ; <br><strong>Syndromes :</strong> <span class=\"kw-def\">épilepsie</span>-absence enfant, <span class=\"kw-def\">épilepsie</span> myoclonique juvénile, EGTC du réveil ; <br><strong>Nuance :</strong> <span class=\"kw-clinique\">pas de correspondance stricte</span> entre diagnostic syndromique et <span class=\"kw-etio\">génétique</span> — un même génotype peut correspondre à plusieurs phénotypes (et inversement).</td></tr>\n          <tr><td><b>Infectieuse</b></td><td><strong>Aiguë :</strong> <span class=\"kw-def\">méningo-encéphalite</span> herpétique, neuropaludisme, <span class=\"kw-clinique\">abcès</span> ; <br><strong>Séquellaire :</strong> <span class=\"kw-def\">tuberculose</span> neuro-méningée, neurocysticercose.</td></tr>\n          <tr><td><b>Métabolique</b></td><td><strong><span class=\"kw-etio\">Acquise</span> :</strong> hypoglycémie, dysnatrémie, dyscalcémie, hyperammoniémie ; <br><strong><span class=\"kw-etio\">Héréditaire</span> :</strong> maladies mitochondriales, déficit GLUT1, leucodystrophies.</td></tr>\n          <tr><td><b>Dysimmune</b></td><td><strong>Auto-Ac :</strong> encéphalites à Ac anti-NMDA, anti-LGI1, anti-CASPR2 ; <br><strong><span class=\"kw-etio\">Inflammatoire</span> :</strong> sclérose en plaques (rare), Rasmussen.</td></tr>\n          <tr><td><b>Inconnue</b></td><td>Aucune étiologie identifiée malgré bilan complet (anciennement \"cryptogénique\").</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège annales.</strong> L'<span class=\"kw-imagerie\">IRM</span> cérébrale est <span class=\"kw-clinique\">systématique devant toute épilepsie</span>, SAUF si syndrome d'origine <span class=\"kw-etio\">génétique</span> précis cliniquement et <span class=\"kw-imagerie\">EEG</span> typique (ex : <span class=\"kw-def\">épilepsie</span>-absence enfant). Ne pas cocher l'<span class=\"kw-imagerie\">IRM</span> dans ce contexte. ⭐\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 340 — <span class=\"kw-etio\">AVC</span> · 341 — Hémorragie méningée · 100 — <span class=\"kw-clinique\">Céphalée</span></em></p>","frequence":5},{"id":"105-5","rang":"B","rubrique":"Eléments physiopathologiques","titre":"Connaître les principaux facteurs de risque de survenue d'une crise","contenu":"<p>Les <span class=\"kw-def\">facteurs précipitants</span> (ou facteurs déclenchants) abaissent transitoirement le <span class=\"kw-def\">seuil épileptogène</span> chez un patient prédisposé OU déclenchent une crise occasionnelle chez un sujet sans <span class=\"kw-def\">épilepsie</span>.</p>\n\n      <table >\n        <thead><tr><th>Catégorie</th><th>Facteurs</th></tr></thead>\n        <tbody>\n          <tr><td><b>Hygiène de vie</b></td><td><strong>Sommeil :</strong> <span class=\"kw-clinique\">privation</span>, dette chronique, jet-lag ; <br><strong><span class=\"kw-etio\">Alcool</span> :</strong> <span class=\"kw-clinique\">ivresse aiguë</span>, <span class=\"kw-etio\">sevrage</span> chez l'éthylique chronique ; <br><strong>Stress :</strong> physique (effort intense) ou psychique.</td></tr>\n          <tr><td><b>Métaboliques</b></td><td><strong><span class=\"kw-bio\">Glycémie</span> :</strong> hypo <span class=\"kw-chiffre\">&lt; 0,5 g/L</span>, hyper ; <br><strong>Ions :</strong> hypo-/hyper-<span class=\"kw-bio\">natrémie</span>, hypocalcémie, hypomagnésémie ; <br><strong>Organes :</strong> <span class=\"kw-ci\">insuffisance rénale</span> ou hépatique avancée.</td></tr>\n          <tr><td><b>Iatrogènes</b></td><td><strong>Surdosage :</strong> tricycliques, neuroleptiques, <span class=\"kw-ttt\">lithium</span>, <span class=\"kw-ttt\">isoniazide</span>, théophylline, xylocaïne, <span class=\"kw-ttt\">tramadol</span>, quinolones ; <br><strong><span class=\"kw-ttt\">Sevrage</span> :</strong> <span class=\"kw-etio\">benzodiazépines</span>, <span class=\"kw-etio\">barbituriques</span> ; <br><strong><span class=\"kw-ci\">Mauvaise observance</span> :</strong> oubli antiépileptique, sous-dosage (cause n°1 chez le patient connu).</td></tr>\n          <tr><td><b>Toxiques</b></td><td><strong>Drogues :</strong> <span class=\"kw-etio\">cocaïne</span>, amphétamines, MDMA ; <br><strong>Environnement :</strong> intoxication <span class=\"kw-bio\">CO</span>.</td></tr>\n          <tr><td><b>Stimulations sensorielles</b></td><td><strong><span class=\"kw-clinique\">Photosensibilité</span> :</strong> <span class=\"kw-clinique\">SLI</span>, écrans, jeux vidéo (épilepsies photosensibles, <span class=\"kw-chiffre\">~5 %</span>) ; <br><strong>Fébrile :</strong> <span class=\"kw-clinique\">hyperthermie</span> chez l'enfant <span class=\"kw-chiffre\">&lt; 5 ans</span> (cf. obj-8).</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Toute nouvelle crise chez un patient épileptique connu doit faire <span class=\"kw-clinique\">rechercher un facteur déclenchant</span> : observance, sommeil, alcool, <span class=\"kw-clinique\">fièvre</span>, médicament récent. Un facteur précipitant trouvé ne suffit PAS à reclasser l'épilepsie en \"crise symptomatique aiguë\".\n      </div>","frequence":0},{"id":"105-6","rang":"A","rubrique":"Etiologies","titre":"Connaître les principales causes d'épilepsies","contenu":"<p>Distinguer impérativement les <span class=\"kw-def\">crises symptomatiques aiguës</span> (provoquées, &lt; <span class=\"kw-chiffre\">7 jours</span> d'une <span class=\"kw-clinique\">lésion</span> cérébrale aiguë, pas une <span class=\"kw-def\">épilepsie</span>) des <span class=\"kw-def\">épilepsies vraies</span> (maladie chronique). Le tableau ci-dessous synthétise les causes <b>aiguës provoquées</b> à éliminer en <span class=\"kw-chiffre\">première intention</span>.</p>\n\n      <table >\n        <thead><tr><th>Catégorie</th><th>Causes principales</th></tr></thead>\n        <tbody>\n          <tr><td><b>Métaboliques</b> (souvent CGTC)</td><td><strong><span class=\"kw-bio\">Glycémie</span> :</strong> hypoglycémie, hyperglycémie ; <br><strong><span class=\"kw-bio\">Calcémie</span> :</strong> hypo- et hypercalcémie ; <br><strong><span class=\"kw-bio\">Natrémie</span> :</strong> hypo- et <span class=\"kw-alerte\">hypernatrémie</span> ; <br><strong><span class=\"kw-bio\">Magnésémie</span> :</strong> hypomagnésémie ; <br><strong>Organes :</strong> <span class=\"kw-def\">IRC</span> avancée, <span class=\"kw-ci\">insuffisance hépatique</span> avancée.</td></tr>\n          <tr><td><b>Toxiques</b></td><td><strong>OH :</strong> ivresse convulsivante, crise de <span class=\"kw-ttt\">sevrage</span> (h à <span class=\"kw-chiffre\">3 j</span> post-arrêt), <span class=\"kw-def\">épilepsie</span> alcoolique ; <br><strong>Médicaments :</strong> surdosage tricycliques/neuroleptiques/<span class=\"kw-ttt\">lithium</span>/<span class=\"kw-ttt\">isoniazide</span>/théophylline/xylocaïne, sevrage BZD/barbituriques ; <br><strong>Drogues :</strong> cocaïne ; <br><strong><span class=\"kw-etio\">Toxique</span> inhalé :</strong> monoxyde de carbone.</td></tr>\n          <tr><td><b>Infectieuses</b></td><td><strong>Méninges :</strong> <span class=\"kw-def\">méningite</span>, <span class=\"kw-def\">méningo-encéphalite</span> (<span class=\"kw-alerte\">signe de gravité</span>) ; <br><strong>Encéphale :</strong> <span class=\"kw-def\">encéphalite</span> herpétique (<span class=\"kw-etio\">HSV</span>) ; <br><strong>Collection :</strong> <span class=\"kw-clinique\">abcès</span> cérébral.</td></tr>\n          <tr><td><b>Vasculaires</b></td><td><strong><span class=\"kw-etio\">AVC</span> :</strong> <span class=\"kw-etio\">ischémique</span>, <span class=\"kw-etio\">hémorragique</span>, thrombophlébite, HSA (crises précoces ou <span class=\"kw-def\">épilepsie</span> vasculaire séquellaire) ; <br><strong>Malformations :</strong> MAV non rompue, <span class=\"kw-etio\">cavernome</span> ; <br><strong>Autre :</strong> encéphalopathie hypertensive aiguë (PRES), angéite cérébrale.</td></tr>\n          <tr><td><b>Traumatiques</b></td><td><strong>TC sévère :</strong> crises précoces ou <span class=\"kw-def\">épilepsie</span> post-traumatique chronique ; <br><strong>Hématome :</strong> HSD chronique (peut se révéler par une crise).</td></tr>\n          <tr><td><b>Tumorales</b> (~<span class=\"kw-chiffre\">10 %</span> des épilepsies adulte)</td><td><strong>Bas <span class=\"kw-def\">grade</span> :</strong> astrocytome, oligodendrogliome, méningiome ; <br><strong>Haut grade :</strong> glioblastome ; <br><strong>Secondaire :</strong> <span class=\"kw-etio\">métastase cérébrale</span>. <span class=\"kw-clinique\">Surtout les tumeurs à développement lent.</span></td></tr>\n          <tr><td><b>Dysimmunes</b></td><td><strong>Auto-immunes non paranéoplasiques :</strong> <span class=\"kw-def\">encéphalite</span> à <span class=\"kw-bio\">Ac anti-NMDA-R</span>, anti-LGI1, anti-CASPR2, neurolupus ; <br><strong>Auto-immunes paranéoplasiques :</strong> recherche d'un cancer sous-jacent (pulmonaire, ovarien, tératome).</td></tr>\n          <tr><td><b>Autres</b></td><td>Anoxie cérébrale, éclampsie.</td></tr>\n        </tbody>\n      </table>\n\n      <p><span class=\"kw-def\">Causes selon l'âge</span> — exigible à l'EDN :</p>\n\n      <table >\n        <thead><tr><th>Groupe d'âge</th><th>Causes fréquentes</th></tr></thead>\n        <tbody>\n          <tr><td><b>Nouveau-né</b></td><td><strong>Infectieuse :</strong> <span class=\"kw-def\">méningite</span> <span class=\"kw-etio\">bactérienne</span> néonatale ; <br><strong>Anoxie :</strong> périnatale ; <br><strong>Métabolique :</strong> hypoglycémie, hypocalcémie, déficit en pyridoxine (vit B6).</td></tr>\n          <tr><td><b>Nourrisson & jeune enfant</b></td><td><strong>Fébrile :</strong> <span class=\"kw-clinique\">convulsions</span> fébriles (cf. obj-8) ; <br><strong>Infectieuse :</strong> <span class=\"kw-def\">méningite</span> <span class=\"kw-etio\">bactérienne</span> ; <br><strong>Collection :</strong> HSD chronique ; <br><strong>Métabolique :</strong> hypocalcémie, hypoglycémie, <span class=\"kw-clinique\">déshydratation</span>.</td></tr>\n          <tr><td><b>Adulte</b></td><td><strong>OH :</strong> <span class=\"kw-ttt\">sevrage</span> éthylique ; <br><strong>Tumeur :</strong> primitive ou métastase ; <br><strong>Vasculaire :</strong> <span class=\"kw-etio\">AVC</span> ; <br><strong>Séquelle :</strong> post-TC, HSD chronique ; <br><strong>Sclérose :</strong> hippocampique (<span class=\"kw-def\">épilepsie</span> temporale interne).</td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"105-7","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques d'une crise épileptique tonicoclonique, de myoclonies, d'absences typiques, de quelques crises focales telles que les crises de la région centrale, les crises temporales internes","contenu":"<p>La <span class=\"kw-def\">sémiologie des crises</span> est l'élément central du <span class=\"kw-def\">diagnostic positif</span> : elle oriente vers le type (généralisée ou focale) et la topographie. Interrogatoire de l'entourage indispensable.</p>\n\n      <h5>Crise généralisée tonico-clonique (CGTC) — 3 phases stéréotypées</h5>\n\n      <figure class=\"frise-cgtc\" aria-label=\"Frise chronologique des 3 phases d'une crise généralisée tonico-clonique : tonique, clonique, résolutive\">\n        <div class=\"frise-cgtc__phase frise-cgtc__phase--tonique\">\n          <span class=\"frise-cgtc__dur\">10–30 s</span>\n          <h6 class=\"frise-cgtc__name\">1 · Phase tonique</h6>\n          <ul class=\"frise-cgtc__signs\">\n            <li><strong>Conscience</strong> perdue d'emblée + cri initial (spasme laryngé)</li>\n            <li>Contraction tonique généralisée : flexion → extension</li>\n            <li>Apnée → <span class=\"kw-clinique\">cyanose</span> ; <strong>morsure latérale de langue ⭐</strong></li>\n            <li>Végétatifs : <span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-clinique\">HTA</span>, <span class=\"kw-clinique\">mydriase</span>, hypersécrétion</li>\n          </ul>\n        </div>\n        <div class=\"frise-cgtc__phase frise-cgtc__phase--clonique\">\n          <span class=\"frise-cgtc__dur\">20–30 s →<span class=\"kw-chiffre\"> 1-2 min</span></span>\n          <h6 class=\"frise-cgtc__name\">2 · Phase clonique</h6>\n          <ul class=\"frise-cgtc__signs\">\n            <li>Secousses musculaires bilatérales, symétriques, synchrones</li>\n            <li>Amplitude <span class=\"kw-clinique\">décroissante</span></li>\n            <li>Respiration stertoreuse à la levée du spasme</li>\n          </ul>\n        </div>\n        <div class=\"frise-cgtc__phase frise-cgtc__phase--resolutive\">\n          <span class=\"frise-cgtc__dur\">min → dizaines de min</span>\n          <h6 class=\"frise-cgtc__name\">3 · Phase résolutive (post-critique)</h6>\n          <ul class=\"frise-cgtc__signs\">\n            <li><span class=\"kw-clinique\">Coma</span> hypotonique, aréactif ; respiration stertoreuse</li>\n            <li>Énurésie (perte d'urines) fréquente</li>\n            <li>Reprise : <span class=\"kw-clinique\">confusion</span> + amnésie totale de la crise</li>\n            <li><span class=\"kw-clinique\">Céphalées</span>, courbatures</li>\n          </ul>\n        </div>\n      </figure>\n      <p class=\"frise-cgtc__caption\">Séquence stéréotypée chez un même patient. Repères d'annales : morsure <em>latérale</em> (<span class=\"kw-bio\">vs</span> pointe = psychogène), amnésie totale, confusion post-critique absente dans la <span class=\"kw-clinique\">syncope</span>.</p>\n\n      <h5>Myoclonies</h5>\n      <p><span class=\"kw-clinique\">Secousses musculaires brèves, brutales, bilatérales (souvent membres supérieurs)</span>, sans perte de conscience (sauf généralisation secondaire). Souvent au réveil → évoquer une <b><span class=\"kw-def\">épilepsie</span> myoclonique juvénile</b>. <strong><span class=\"kw-imagerie\">EEG</span> percritique :</strong> <span class=\"kw-bio\">polypointes-ondes bilatérales, symétriques, synchrones</span>.</p>\n\n      <h5>Absence typique de l'enfant</h5>\n      <p><span class=\"kw-clinique\">Rupture brutale et complète du contact</span>, regard fixe, durée <span class=\"kw-chiffre\">2-20 s</span>, début et fin brusques, <b>pas de chute, pas de <span class=\"kw-clinique\">confusion</span> post-critique</b>, possibles automatismes oraux (mâchonnements, clignements). <span class=\"kw-imagerie\">EEG</span> = <span class=\"kw-bio\">pointes-ondes généralisées à 3 Hz</span> bilatérales et synchrones. Déclenchée par l'<span class=\"kw-clinique\">hyperpnée</span>.</p>\n\n      <h5>Crises focales — exemples obligatoires EDN</h5>\n\n      <table >\n        <thead><tr><th>Type</th><th>Sémiologie</th></tr></thead>\n        <tbody>\n          <tr><td><b>Région centrale (Bravais-Jackson)</b></td><td><strong>Topographie :</strong> cortex moteur (frontal ascendant) ; <br><strong>Motricité :</strong> clonies débutant à un segment de membre (pouce, commissure labiale), <span class=\"kw-clinique\">\"marche jacksonienne\"</span> avec extension de proche en proche selon l'homonculus ; <br><strong>Post-critique :</strong> <span class=\"kw-clinique\">déficit moteur</span> transitoire = paralysie de Todd.</td></tr>\n          <tr><td><b>Temporales internes</b></td><td><strong>Aura :</strong> sensation épigastrique ascendante, peur, <span class=\"kw-clinique\">déjà-vu/jamais-vu</span>, hallucinations olfactives ou auditives ; <br><strong>Phase clinique :</strong> <span class=\"kw-alerte\">rupture</span> de contact, <b>automatismes oro-alimentaires</b> (mâchonnements, déglutition) + automatismes gestuels (manipulation) ; <br><strong>Durée :</strong> <span class=\"kw-chiffre\">prolongée &gt; 1 min</span> (signe distinctif <span class=\"kw-bio\">vs</span> absence) ; <br><strong><span class=\"kw-clinique\">Évolution</span> :</strong> peut généraliser secondairement ; <br><strong>Cause fréquente :</strong> <span class=\"kw-etio\">sclérose hippocampique</span>.</td></tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 100 — <span class=\"kw-clinique\">Céphalée</span> · 343 — Etat confusionnel - trouble de conscience</em></p>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/mesial-temporal-sclerosis","label":"Radiopaedia : Mesial temporal sclerosis"}]},{"id":"105-8","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les diagnostics différentiels des crises d'épilepsie","contenu":"<p>L'erreur classique est de coller l'étiquette \"<span class=\"kw-def\">épilepsie</span>\" sur tout <span class=\"kw-clinique\">malaise</span>. Avant de retenir le diagnostic, il faut éliminer les <span class=\"kw-def\">diagnostics différentiels</span> selon la sémiologie de présentation.</p>\n\n      <table >\n        <thead><tr><th>Si présentation comme…</th><th>DD à éliminer</th></tr></thead>\n        <tbody>\n          <tr><td><b>Crise généralisée tonico-clonique</b></td><td><strong><span class=\"kw-clinique\">Syncope</span> :</strong> convulsive (myoclonies brèves) ou réflexe vagale (prodromes, <span class=\"kw-clinique\">pâleur</span>, <span class=\"kw-clinique\">sueurs</span>, récupération rapide sans <span class=\"kw-clinique\">confusion</span>) ; <br><strong>CNEP :</strong> crise non épileptique psychogène (mouvements anarchiques, durée prolongée, yeux fermés résistants à l'ouverture, post-critique absent) ; <br><strong>Hypoglycémie :</strong> contexte <span class=\"kw-def\">diabète</span>, <span class=\"kw-bio\">glycémie capillaire</span> systématique.</td></tr>\n          <tr><td><b>Crise focale</b></td><td><strong><span class=\"kw-def\">Migraine</span> :</strong> aura migraineuse (scotome scintillant, marche &gt; <span class=\"kw-chiffre\">5 min</span>, suivie de <span class=\"kw-clinique\">céphalée</span>) ; <br><strong>Vasculaire :</strong> <span class=\"kw-def\">AIT</span> (déficit négatif, sans marche) ; <br><strong>Métabolique :</strong> <span class=\"kw-clinique\">malaise</span> hypoglycémique focal ; <br><strong>Psychiatrique :</strong> attaque de panique avec déréalisation.</td></tr>\n          <tr><td><b>Absence</b></td><td><strong>Inattention :</strong> rêverie scolaire (interruptible par l'appel, pas d'arrêt brutal) ; <br><strong>Tic / TOC ;</strong> <br><strong>Crise focale avec <span class=\"kw-alerte\">rupture</span> de contact :</strong> durée plus longue, automatismes, post-critique présent.</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> La <span class=\"kw-clinique\">syncope convulsive</span> (hypoperfusion cérébrale → quelques myoclonies brèves) est très souvent confondue avec une CGTC. Discriminants : prodromes vagaux, <span class=\"kw-clinique\">durée des secousses &lt; 15 s</span>, pas de morsure latérale de langue, récupération <span class=\"kw-chiffre\">&lt; 1 min</span> sans <span class=\"kw-clinique\">confusion</span>. <span class=\"kw-bio\">ECG</span> systématique.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 100 — <span class=\"kw-clinique\">Céphalée</span> · 343 — Etat confusionnel - trouble de conscience</em></p>","frequence":0},{"id":"105-9","rang":"A","rubrique":"Diagnostic positif","titre":"Identifier des convulsions fébriles et leur pronostic selon les critères de gravité","contenu":"<p><span class=\"kw-def\">Convulsion fébrile (CF)</span> = <span class=\"kw-def\">crise épileptique</span> survenant chez un enfant de <span class=\"kw-chiffre\">6 mois à 5 ans</span>, dans le contexte d'une <b><span class=\"kw-clinique\">fièvre</span> <span class=\"kw-chiffre\">≥ 38 °C</span></b> sans <span class=\"kw-def\">infection neuro-méningée</span> ni autre cause neurologique identifiée. <span class=\"kw-def\">Incidence</span> <span class=\"kw-chiffre\">~2-5 %</span> des enfants. Pic <span class=\"kw-chiffre\">12-18 mois</span>.</p>\n\n      <table >\n        <thead><tr><th>Type</th><th>Critères</th><th><span class=\"kw-def\">Pronostic</span></th></tr></thead>\n        <tbody>\n          <tr><td><b>CF simple</b> <span class=\"kw-chiffre\">(~75 %)</span></td><td><strong>Âge :</strong> <span class=\"kw-chiffre\">≥ 1 an</span> (un âge &lt;<span class=\"kw-chiffre\"> 1 an</span> est un <span class=\"kw-def\">critère de</span> complexité) ; <br><strong>Crise :</strong> <span class=\"kw-clinique\">généralisée tonico-clonique</span> ; <br><strong>Durée :</strong> <span class=\"kw-chiffre\">&lt; 15 min</span> ; <br><strong>Unique :</strong> sur <span class=\"kw-chiffre\">24 h</span> ; <br><strong>Post-critique :</strong> récupération neurologique complète <span class=\"kw-chiffre\">&lt; 1 h</span>.</td><td><span class=\"kw-clinique\">Excellent</span> — pas d'imagerie, pas d'<span class=\"kw-imagerie\">EEG</span>, pas de PL systématique (si examen rassurant). Risque d'<span class=\"kw-def\">épilepsie</span> ultérieure <span class=\"kw-chiffre\">~1-2 %</span> (proche population générale).</td></tr>\n          <tr><td><b>CF complexe</b> <span class=\"kw-chiffre\">(~25 %)</span></td><td><strong>Au moins 1 critère :</strong> <span class=\"kw-chiffre\">âge &lt; 1 an</span> ; <br>durée <span class=\"kw-chiffre\">&gt; 15 min</span> ; <br><span class=\"kw-clinique\">crise focale</span> ou avec <span class=\"kw-clinique\">déficit post-critique (Todd)</span> ; <br>répétée dans les <span class=\"kw-chiffre\">24 h</span> ; <br>récupération neurologique prolongée.</td><td><span class=\"kw-alerte\">Réservé</span> — bilan élargi (PL si signes méningés/&lt; <span class=\"kw-chiffre\">18 mois</span>, <span class=\"kw-imagerie\">EEG</span>, imagerie selon contexte). Risque d'<span class=\"kw-def\">épilepsie</span> ultérieure <span class=\"kw-chiffre\">~5-10 %</span>.</td></tr>\n        </tbody>\n      </table>\n\n      <h5>Conduite à tenir en aigu</h5>\n      <p><strong>Si crise <span class=\"kw-chiffre\">&gt; 5 min</span> :</strong> <span class=\"kw-ttt\">diazépam 0,5 mg/kg intra-rectal</span> <span class=\"kw-chiffre\">(max 10 mg)</span>, ou <span class=\"kw-ttt\">midazolam buccal 0,3 mg/kg</span>. <strong>Antipyrétique :</strong> <span class=\"kw-ttt\">paracétamol 15 mg/kg</span>. <strong>Rechercher la cause de la <span class=\"kw-clinique\">fièvre</span></strong> (<span class=\"kw-clinique\">otite</span>, ORL, exanthème subit, urinaire). <span class=\"kw-alerte\">PL systématique si &lt; 12 mois ou signes méningés.</span></p>\n\n      <div class=\"callout callout-warn\">\n        <strong>À ne pas confondre.</strong> Les CF NE sont PAS une <span class=\"kw-def\">épilepsie</span> : ce sont des <span class=\"kw-def\">crises symptomatiques aiguës provoquées par la fièvre</span>. Pas de traitement antiépileptique de fond. Information rassurante des parents + plan d'<span class=\"kw-alerte\">urgence</span> (<span class=\"kw-ttt\">diazépam</span> IR à domicile si CF prolongée connue).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 47 — <span class=\"kw-def\">Suivi</span> d'un nourrisson, d'un enfant, d'un adolescent · 56 — Enfant handicapé</em></p>","frequence":1},{"id":"105-10","rang":"A","rubrique":"Prise en charge","titre":"Connaître la conduite à tenir en présence d'une crise généralisée tonico-clonique","contenu":"<p>Conduite à tenir <span class=\"kw-def\">simple, codifiée, à connaître par tout médecin</span>. Distinction nette entre la crise isolée (qui cède spontanément) et l'EMETCG (qui nécessite des BZD IV, cf. obj-10).</p>\n\n      <table >\n        <thead><tr><th>Étape</th><th>Geste</th></tr></thead>\n        <tbody>\n          <tr><td><b>1. Sécuriser</b></td><td><strong>Environnement :</strong> dégager les objets dangereux, éloigner mobilier ; <br><strong>Tête :</strong> protéger d'un coussin ou des mains (éviter traumatisme) ; <br><strong>Ne PAS :</strong> introduire d'objet dans la bouche, contraindre les mouvements.</td></tr>\n          <tr><td><b>2. Observer & chronométrer</b></td><td><strong>Sémiologie :</strong> début, latéralisation, phases ; <br><strong>Durée :</strong> chronométrer (élément clé pour la suite) ; <br><strong>Conscience :</strong> évaluer la récupération post-critique.</td></tr>\n          <tr><td><b>3. Phase résolutive</b></td><td><strong>Position :</strong> <span class=\"kw-ttt\">PLS</span> (latérale de sécurité) ; <br><strong>Liberté VAS :</strong> aspiration des sécrétions, <span class=\"kw-ttt\">canule de Guedel</span> ; <br><strong><span class=\"kw-ttt\">Oxygénothérapie</span> :</strong> masque haute concentration <span class=\"kw-chiffre\">10 L/min</span> ; <br><strong>Voie veineuse :</strong> 2 VVP +<span class=\"kw-chiffre\"> 1 L</span> <span class=\"kw-ttt\">NaCl 0,9 %</span> ; <br><strong><span class=\"kw-bio\">Glycémie capillaire</span> :</strong> systématique (resucrage si hypoglycémie).</td></tr>\n          <tr><td><b>4. Évaluer l'<span class=\"kw-alerte\">urgence</span></b></td><td><strong>Crise <span class=\"kw-chiffre\">&gt; 5 min</span> OU répétée sans reprise de conscience :</strong> <span class=\"kw-alerte\">EMETCG → BZD IV/IR (cf. obj-10) + appel SAMU</span> ; <br><strong>Crise isolée <span class=\"kw-chiffre\">&lt; 5 min</span> cédant spontanément :</strong> <span class=\"kw-def\">surveillance</span>, bilan en différé.</td></tr>\n          <tr><td><b>5. Bilan post-crise (1<sup>ère</sup> crise)</b></td><td><strong>Biologie :</strong> <span class=\"kw-bio\">glycémie</span>, <span class=\"kw-bio\">ionogramme</span> + <span class=\"kw-bio\">calcémie</span> + <span class=\"kw-bio\">magnésémie</span>, <span class=\"kw-bio\">urée</span>/créat, <span class=\"kw-bio\">bilan hépatique</span>, <span class=\"kw-bio\">ammoniémie</span>, hémostase, <span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">β-hCG</span> (femme), ± toxiques/<span class=\"kw-etio\">OH</span>/BZD/<span class=\"kw-bio\">HbCO</span> ; <br><strong><span class=\"kw-imagerie\">EEG</span> :</strong> dans les <span class=\"kw-chiffre\">&lt; 24 h</span> (seul examen contribuant au <span class=\"kw-def\">diagnostic positif</span>) ; <br><strong>Imagerie :</strong> <span class=\"kw-imagerie\">TDM</span>/<span class=\"kw-imagerie\">IRM</span> cérébrale ; <br><strong><span class=\"kw-bio\">ECG</span> :</strong> systématique (éliminer une cause cardiaque).</td></tr>\n        </tbody>\n      </table>\n\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewBox=\"0 0 560 312\" role=\"img\" aria-label=\"Frise de la conduite à tenir devant une crise généralisée tonico-clonique en cinq étapes séquentielles. Étape 1, sécuriser : dégager l'environnement et protéger la tête, sans rien introduire dans la bouche. Étape 2, observer et chronométrer la durée de la crise. Étape 3, à la phase résolutive : position latérale de sécurité, liberté des voies aériennes, oxygène et glycémie capillaire. Étape 4, évaluer l'urgence selon le seuil de cinq minutes. Si la crise dépasse cinq minutes ou se répète sans reprise de conscience, c'est un état de mal épileptique tonico-clonique imposant des benzodiazépines intraveineuses ou rectales et l'appel du SAMU. Si la crise isolée cède spontanément en moins de cinq minutes, on poursuit par surveillance puis l'étape 5, bilan post-crise en différé : biologie, électroencéphalogramme dans les vingt-quatre heures, imagerie cérébrale et électrocardiogramme.\" style=\"height:auto;display:block;border-radius:8px\">\n          <text class=\"tx-title\" x=\"280\" y=\"18\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"600\">CAT devant une CGTC — 5 étapes</text>\n\n          <rect class=\"fb-teal\" x=\"10\" y=\"32\" width=\"100\" height=\"56\" rx=\"6\"/>\n          <text class=\"tx-teal\" x=\"60\" y=\"52\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\">1 · Sécuriser</text>\n          <text class=\"tx-teal\" x=\"60\" y=\"68\" text-anchor=\"middle\" font-size=\"9\">dégager, protéger</text>\n          <text class=\"tx-teal\" x=\"60\" y=\"80\" text-anchor=\"middle\" font-size=\"9\">la tête</text>\n\n          <line class=\"ln\" x1=\"110\" y1=\"60\" x2=\"124\" y2=\"60\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"130,60 122,55 122,65\"/>\n\n          <rect class=\"fb-teal\" x=\"132\" y=\"32\" width=\"100\" height=\"56\" rx=\"6\"/>\n          <text class=\"tx-teal\" x=\"182\" y=\"50\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\">2 · Observer</text>\n          <text class=\"tx-teal\" x=\"182\" y=\"64\" text-anchor=\"middle\" font-size=\"9.5\">chronométrer</text>\n          <text class=\"tx-teal\" x=\"182\" y=\"78\" text-anchor=\"middle\" font-size=\"9.5\">la durée</text>\n\n          <line class=\"ln\" x1=\"232\" y1=\"60\" x2=\"246\" y2=\"60\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"252,60 244,55 244,65\"/>\n\n          <rect class=\"fb-teal\" x=\"254\" y=\"32\" width=\"100\" height=\"56\" rx=\"6\"/>\n          <text class=\"tx-teal\" x=\"304\" y=\"46\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\">3 · Phase<tspan x=\"304\" dy=\"11\">résolutive</tspan></text>\n          <text class=\"tx-teal\" x=\"304\" y=\"71\" text-anchor=\"middle\" font-size=\"9.5\">PLS, VAS, O₂</text>\n          <text class=\"tx-teal\" x=\"304\" y=\"83\" text-anchor=\"middle\" font-size=\"9.5\"><span class=\"kw-bio\">glycémie</span> cap.</text>\n\n          <line class=\"ln\" x1=\"354\" y1=\"60\" x2=\"368\" y2=\"60\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"374,60 366,55 366,65\"/>\n\n          <rect class=\"fb-amber\" x=\"376\" y=\"32\" width=\"110\" height=\"56\" rx=\"6\"/>\n          <text class=\"tx-amber\" x=\"431\" y=\"50\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\">4 · Évaluer</text>\n          <text class=\"tx-amber\" x=\"431\" y=\"64\" text-anchor=\"middle\" font-size=\"9.5\">l'<span class=\"kw-alerte\">urgence</span></text>\n          <text class=\"tx-amber\" x=\"431\" y=\"78\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"700\">seuil <span class=\"kw-chiffre\">5 min</span></text>\n\n          <line class=\"ln\" x1=\"431\" y1=\"88\" x2=\"431\" y2=\"104\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"160\" y1=\"104\" x2=\"431\" y2=\"104\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"160\" y1=\"104\" x2=\"160\" y2=\"120\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"160,126 155,118 165,118\"/>\n          <text class=\"tx-grey\" x=\"285\" y=\"100\" text-anchor=\"middle\" font-size=\"9.5\">crise isolée &lt;<span class=\"kw-chiffre\"> 5 min</span>, cède seule</text>\n          <line class=\"ln\" x1=\"431\" y1=\"104\" x2=\"431\" y2=\"120\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"431,126 426,118 436,118\"/>\n          <text class=\"tx-red\" x=\"431\" y=\"100\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\">&gt;<span class=\"kw-chiffre\"> 5 min</span> ou répétée</text>\n\n          <rect class=\"fb-ok\" x=\"60\" y=\"128\" width=\"200\" height=\"44\" rx=\"6\"/>\n          <text class=\"tx-ok\" x=\"160\" y=\"147\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\"><span class=\"kw-def\">Surveillance</span></text>\n          <text class=\"tx-ok\" x=\"160\" y=\"163\" text-anchor=\"middle\" font-size=\"9.5\">bilan en différé →</text>\n\n          <rect class=\"fb-red\" x=\"326\" y=\"128\" width=\"210\" height=\"44\" rx=\"6\"/>\n          <text class=\"tx-red\" x=\"431\" y=\"146\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\">EMETCG (<span class=\"kw-alerte\">état de mal</span>)</text>\n          <text class=\"tx-red\" x=\"431\" y=\"162\" text-anchor=\"middle\" font-size=\"9.5\">BZD IV/IR + appel <span class=\"kw-alerte\">SAMU</span> (obj-10)</text>\n\n          <line class=\"ln\" x1=\"160\" y1=\"172\" x2=\"160\" y2=\"216\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"160\" y1=\"216\" x2=\"280\" y2=\"216\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"280\" y1=\"216\" x2=\"280\" y2=\"232\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"280,238 275,230 285,230\"/>\n\n          <rect class=\"fb-grey\" x=\"40\" y=\"240\" width=\"480\" height=\"56\" rx=\"6\"/>\n          <text class=\"tx-grey\" x=\"280\" y=\"259\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\">5 · Bilan post-crise (1ᵉʳᵉ crise)</text>\n          <text class=\"tx-grey\" x=\"280\" y=\"275\" text-anchor=\"middle\" font-size=\"9.5\">biologie · <span class=\"kw-imagerie\">EEG</span> &lt;<span class=\"kw-chiffre\"> 24 h</span> · imagerie cérébrale (<span class=\"kw-imagerie\">TDM</span>/<span class=\"kw-imagerie\">IRM</span>) · <span class=\"kw-imagerie\">ECG</span></text>\n          <text class=\"tx-grey\" x=\"280\" y=\"289\" text-anchor=\"middle\" font-size=\"9\"><span class=\"kw-imagerie\">EEG</span> en urgence seulement si suspicion d'EME</text>\n        </svg>\n        <figcaption>Séquence procédurale stéréotypée ; le seuil des <span class=\"kw-chiffre\">5 min</span> à l'étape 4 fait basculer vers l'<span class=\"kw-alerte\">état de mal</span> (BZD en urgence, cf. obj-10).</figcaption>\n      </figure>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> La <span class=\"kw-clinique\">PLS post-critique</span> est non négociable. L'<span class=\"kw-imagerie\">EEG</span> normal n'exclut PAS le diagnostic d'<span class=\"kw-def\">épilepsie</span> (sensibilité ~<span class=\"kw-chiffre\">50 %</span> en intercritique). La <span class=\"kw-alerte\">seule indication de l'EEG en urgence est la suspicion d'EME</span>.\n      </div>","frequence":3},{"id":"105-11","rang":"B","rubrique":"Prise en charge","titre":"Connaître les grands principes traitement de l'état de mal convulsif avec la posologie des benzodiazépines IV (ou voie rectale chez l'enfant) (clonazepam ou diazepam)","contenu":"<p><span class=\"kw-alerte\">URGENCE ABSOLUE</span> — l'EMETCG est l'une des rares urgences neurologiques où chaque minute compte. <span class=\"kw-alerte\"><span class=\"kw-def\">Pronostic</span> vital</span> et fonctionnel engagé au-delà de <span class=\"kw-chiffre\">30 min</span>. Schéma <b>graduel en 4 étapes</b>, à passer dès que la précédente échoue ou que la durée s'allonge.</p>\n\n      <table >\n        <thead><tr><th>Étape</th><th>Délai</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr><td><b>1. Mesures générales</b></td><td>T0</td><td><strong>VAS :</strong> liberté, aspiration ; <br><strong>O<sub>2</sub> :</strong> masque haute concentration ; <br><strong>Voie veineuse :</strong> avec sérum salé <span class=\"kw-chiffre\">0,9 %</span> ; <br><strong><span class=\"kw-bio\">Glycémie capillaire</span> :</strong> systématique, resucrage si &lt; <span class=\"kw-chiffre\">0,5 g/L</span> ; <br><strong>Scope :</strong> FC, SpO<sub>2</sub>, PA, FR.</td></tr>\n          <tr><td><b>2. BZD — 1<sup>re</sup> injection</b></td><td>T0 → T5</td><td><strong>Adulte (IV lente) :</strong> <span class=\"kw-ttt\">clonazépam 0,015 mg/kg</span> <span class=\"kw-chiffre\">(max 1,5 mg)</span> OU <span class=\"kw-ttt\">diazépam 0,15 mg/kg</span> IV ; <br><strong>Enfant (intra-rectal) :</strong> <span class=\"kw-ttt\">diazépam 0,5 mg/kg IR</span> <span class=\"kw-chiffre\">(max 10 mg)</span> — voie de référence si pas de VVP ; <br><strong>Buccal :</strong> <span class=\"kw-ttt\">midazolam 0,3 mg/kg</span> en alternative ; <br><strong>Réévaluer à <span class=\"kw-chiffre\">5 min</span>.</strong></td></tr>\n          <tr><td><b>3. BZD — 2<sup>e</sup> injection si persistance</b></td><td>T5 → T10</td><td><strong>Même posologie</strong> (clonazépam OU <span class=\"kw-ttt\">diazépam</span>) ; <br><strong>Préparer l'antiépileptique de relais</strong> (étape 4) ; <br><strong>Surveiller :</strong> <span class=\"kw-def\">dépression</span> respiratoire (<span class=\"kw-ttt\">intubation</span> prête).</td></tr>\n          <tr><td><b>4. Antiépileptique de relais</b></td><td>T10 → T30</td><td><strong>Choix :</strong> <span class=\"kw-ttt\">fosphénytoïne 20 mg/kg IV en 15-20 min</span> OU <span class=\"kw-ttt\">phénobarbital 15 mg/kg IV en 15 min</span> OU <span class=\"kw-ttt\">valproate 40 mg/kg IV en 15 min</span> OU <span class=\"kw-ttt\">lévétiracétam 40 mg/kg IV en 10 min</span> ; <br><strong>Si échec :</strong> EME réfractaire → <span class=\"kw-alerte\">réanimation</span>, <span class=\"kw-clinique\">coma thérapeutique</span> par <span class=\"kw-ttt\">thiopental</span> ou <span class=\"kw-ttt\">midazolam</span>/<span class=\"kw-ttt\">propofol</span> IVSE + IOT/VM + <span class=\"kw-imagerie\">EEG</span> continu.</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Pièges posologiques.</strong> <span class=\"kw-ci\">Pas de diazépam IV chez le nourrisson</span> (risque d'apnée majeur) → IR ou <span class=\"kw-ttt\">midazolam</span> buccal. <span class=\"kw-ci\">Pas de phénytoïne en bolus IV rapide</span> (cardiotoxicité, troubles du rythme) → toujours sous scope, vitesse &lt; <span class=\"kw-chiffre\">50 mg</span>/min. Le <span class=\"kw-ttt\">clonazépam</span> (Rivotril®) a une demi-vie longue et est privilégié en 1<sup>re</sup> intention IV chez l'adulte en France.\n      </div>\n\n      <h5>Choix de l'antiépileptique de relais — profils de tolérance</h5>\n      <table >\n        <thead><tr><th>Molécule</th><th>Profil de tolérance / CI</th></tr></thead>\n        <tbody>\n          <tr><td><b><span class=\"kw-ttt\">Acide valproïque</span></b></td><td><strong>Avantage :</strong> <span class=\"kw-clinique\">meilleur profil cardio-respiratoire</span> (absence d'effets CV/respiratoires) ; <br><strong><span class=\"kw-ci\">CI</span> :</strong> <span class=\"kw-ci\">cirrhose / éthylisme chronique</span> (toxicité hépatique), <span class=\"kw-ci\">femme en âge de procréer</span> (<span class=\"kw-ci\">tératogénicité</span> majeure).</td></tr>\n          <tr><td><b><span class=\"kw-ttt\">Fosphénytoïne</span></b></td><td><strong><span class=\"kw-ci\">CI</span> :</strong> <span class=\"kw-ci\">cardiopathie évoluée</span> (troubles du rythme, <span class=\"kw-clinique\">hypotension</span>) ; <br><strong>Vitesse :</strong> perfusion sous scope obligatoire.</td></tr>\n          <tr><td><b><span class=\"kw-ttt\">Phénytoïne</span> / <span class=\"kw-ttt\">Phénobarbital</span></b></td><td><strong>Effet :</strong> <span class=\"kw-clinique\">dépresseur neurologique, hémodynamique et respiratoire</span> ; <br><strong>Risque :</strong> <span class=\"kw-alerte\">coma</span> <span class=\"kw-etio\">médicamenteux</span> prolongé → préférer l'IOT prête.</td></tr>\n          <tr><td><b><span class=\"kw-ttt\">Lévétiracétam</span></b></td><td><strong>Avantage :</strong> bon profil de tolérance, peu d'interactions ; <br><strong>Réserve :</strong> efficacité parfois inférieure (niveau de preuve insuffisant).</td></tr>\n          <tr><td><b><span class=\"kw-ttt\">Lacosamide</span></b></td><td>Cité dans le CEN, <i>pas dans le MIR</i> — usage 2<sup>e</sup> intention spécialisé.</td></tr>\n        </tbody>\n      </table>","frequence":2,"liens":[{"href":"https://campus.neurochirurgie.fr/article1598.html","label":"Campus Neurochirurgie — Prise en charge crise & EME"}]},{"id":"105-12","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principaux conseils concernant la vie quotidienne chez un patient épileptique","contenu":"<p>L'accompagnement non <span class=\"kw-etio\">médicamenteux</span> est <b>aussi important que le traitement</b>. Il vise à <span class=\"kw-def\">éviter les facteurs précipitants</span>, sécuriser le quotidien et préserver l'insertion scolaire, professionnelle et sociale.</p>\n\n      <table >\n        <thead><tr><th>Domaine</th><th>Conseils</th></tr></thead>\n        <tbody>\n          <tr><td><b>Hygiène de vie</b></td><td><strong>Sommeil :</strong> régularité, <span class=\"kw-chiffre\">≥ 7-8 h/nuit</span>, éviter les nuits blanches (dette de sommeil = facteur précipitant majeur) ; <br><strong><span class=\"kw-etio\">Alcool</span> :</strong> consommation modérée, <span class=\"kw-ci\">jamais d'ivresse</span>, <span class=\"kw-ci\">pas de sevrage brutal</span> ; <br><strong>Drogues :</strong> <span class=\"kw-ci\">cocaïne, héroïne, cannabis non appauvri en THC proscrits</span> ; <br><strong>Excitants :</strong> limiter <span class=\"kw-etio\">café, thé, Coca-Cola caféiné</span> ; <br><strong>Plantes :</strong> éviter sauge, thym, eucalyptus (HE) et <span class=\"kw-ci\">millepertuis</span> (gélule) ; <br><strong>Écrans :</strong> si <span class=\"kw-clinique\">photosensibilité</span> — pauses, distance <span class=\"kw-chiffre\">≥ 2 m</span>, luminosité ambiante allumée.</td></tr>\n          <tr><td><b>Conduite automobile</b></td><td><strong>Permis B (VL) :</strong> <span class=\"kw-clinique\">délai <span class=\"kw-chiffre\">≥ 1 an sans crise</span></span> sous traitement, avis <b>commission médicale du permis</b> (médecin agréé préfecture — pas le médecin traitant) ; <br><strong>Permis lourd (PL, transport en commun, taxi) :</strong> seulement si <span class=\"kw-chiffre\">10 ans de guérison sans récidive ET sans aucun traitement</span> ; <br><strong>Modification de traitement :</strong> <span class=\"kw-chiffre\">6 mois sans crise</span> après changement.</td></tr>\n          <tr><td><b>Risques domestiques</b></td><td><strong>Mobilier :</strong> sans arêtes vives, literie basse ; <br><strong>Eau chaude :</strong> <span class=\"kw-ttt\">limiteur de température</span> (mitigeur thermostatique) ; <br><strong>Cuisine :</strong> protection des <span class=\"kw-clinique\">plaques de cuisson</span> ; <br><strong><span class=\"kw-ci\">Bain</span> :</strong> <span class=\"kw-ci\">jamais de bain non supervisé</span> (préférer douche).</td></tr>\n          <tr><td><b>Scolarité</b></td><td><strong><span class=\"kw-def\">PAI</span></b> (projet d'accueil individualisé) systématique : information enseignants, plan d'<span class=\"kw-alerte\">urgence</span>, <span class=\"kw-ttt\">diazépam IR</span> à l'école si CF connue ; <br><strong>Aménagement :</strong> tiers-temps pour examens, AVS si besoin ; <br><strong>Activités :</strong> autoriser le sport adapté.</td></tr>\n          <tr><td><b>Profession</b></td><td><strong><span class=\"kw-ci\">Interdites</span> :</strong> port d'armes (militaire, policier, gardien de prison), chauffeur professionnel (PL, bus, ambulance), surveillant de baignade, profession du bâtiment (charpentier, zingueur), travail en hauteur, machines dangereuses non sécurisées ; <br><strong>Avis médecine du travail :</strong> systématique ; <br><strong>Inaptitude :</strong> <span class=\"kw-def\">RQTH</span> à instruire.</td></tr>\n          <tr><td><b>Sport & loisirs</b></td><td><strong>Autorisés avec adaptation :</strong> piscine accompagnée, vélo en zone protégée, course à pied ; <br><strong><span class=\"kw-ci\">Interdits formellement</span> :</strong> plongée sous-marine, escalade sans sécurité, tir sportif, saut en parachute ; <br><strong>À éviter :</strong> baignade sans <span class=\"kw-def\">surveillance</span>, équitation, sports mécaniques, sports de combat.</td></tr>\n          <tr><td><b>Contraception & <span class=\"kw-ci\">grossesse</span></b></td><td><strong>Inducteurs enzymatiques :</strong> <span class=\"kw-ttt\">carbamazépine</span>, <span class=\"kw-ttt\">oxcarbazépine</span>, <span class=\"kw-ttt\">eslicarbazépine</span>, <span class=\"kw-ttt\">phénytoïne</span>, <span class=\"kw-ttt\">phénobarbital</span> → réduisent l'efficacité des œstroprogestatifs ; <br><strong>Lamotrigine :</strong> la COP peut <i>diminuer</i> son efficacité (interaction inverse) ; <br><strong>Alternatives :</strong> <span class=\"kw-ttt\">DIU lévonorgestrel</span> ou <span class=\"kw-ttt\">DIU cuivre</span>, méthodes de barrière ; <br><strong><span class=\"kw-ttt\">Valproate</span> :</strong> <span class=\"kw-ci\">contre-indiqué chez la femme en âge de procréer</span> (<span class=\"kw-def\">PPP</span> = programme prévention <span class=\"kw-ci\">grossesse</span>, <span class=\"kw-ci\">tératogénicité</span> majeure + retard cognitif, formulaire annuel obligatoire France depuis 2018) ; <br><strong>Préconception :</strong> <span class=\"kw-ttt\">acide folique <span class=\"kw-chiffre\">5 mg/j</span></span> <span class=\"kw-chiffre\">3 mois avant conception</span> + <span class=\"kw-chiffre\">tout le 1<sup>er</sup> trimestre</span> (prévention <span class=\"kw-clinique\">malformations du tube neural</span>).</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Toute prescription d'antiépileptique chez une femme en âge de procréer doit déclencher un <span class=\"kw-clinique\">conseil contraception + acide folique + information bénéfices/risques</span>. Le <span class=\"kw-ttt\">valproate</span> exige le <b>PPP signé</b> (formulaire annuel obligatoire en France depuis 2018).\n      </div>","frequence":3},{"id":"105-13","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître l'urgence vitale de la prise en charge d'un état de mal épileptique","contenu":"<p><span class=\"kw-alerte\">L'EME est une urgence vitale absolue</span> — au même titre qu'un <span class=\"kw-alerte\">arrêt cardiaque</span> ou un <span class=\"kw-etio\">AVC</span> <span class=\"kw-etio\">ischémique</span>. La fenêtre thérapeutique est étroite et le <span class=\"kw-def\">pronostic</span> se joue dans les <span class=\"kw-chiffre\">30 premières minutes</span>.</p>\n\n      <table >\n        <thead><tr><th>Pourquoi c'est une <span class=\"kw-alerte\">urgence</span></th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><b><span class=\"kw-alerte\"><span class=\"kw-def\">Pronostic</span> vital</span></b></td><td><strong><span class=\"kw-def\">Mortalité</span> :</strong> <span class=\"kw-chiffre\">10-20 %</span> malgré une PEC adaptée ; <br><strong>Causes :</strong> <span class=\"kw-alerte\">détresse</span> respiratoire (apnée, encombrement, <span class=\"kw-def\">OAP</span>), collapsus, <span class=\"kw-alerte\">arrêt cardiaque</span>, cause sous-jacente (<span class=\"kw-def\">méningite</span>, <span class=\"kw-etio\">AVC</span>).</td></tr>\n          <tr><td><b><span class=\"kw-def\">Pronostic</span> fonctionnel</b></td><td><strong>Souffrance neuronale diffuse</strong> par excitotoxicité ; <br><strong>Séquelles potentielles :</strong> troubles attention, troubles cognitifs, détérioration intellectuelle, aggravation ou apparition d'une <span class=\"kw-def\">épilepsie</span> chronique ; <br><strong>Facteurs aggravants :</strong> hypoxie, <span class=\"kw-clinique\">hypotension</span>, hypoglycémie, acidose lactique, <span class=\"kw-clinique\">fièvre</span>.</td></tr>\n          <tr><td><b><span class=\"kw-alerte\">Urgence</span> étiologique</b></td><td>Surtout devant un EME inaugural <span class=\"kw-clinique\">sans ATCD d'épilepsie</span> : éliminer une <span class=\"kw-alerte\">méningite</span>/<span class=\"kw-alerte\">encéphalite</span>, un <span class=\"kw-alerte\">AVC</span>, un HSD, une tumeur, une intoxication. Bilan parallèle au traitement.</td></tr>\n          <tr><td><b>Complications systémiques</b></td><td><strong>Respiratoire :</strong> apnée tonique, inhalation, <span class=\"kw-def\">OAP</span> ; <br><strong>Cardiovasculaire :</strong> poussée <span class=\"kw-def\">HTA</span> initiale, puis <span class=\"kw-clinique\">hypotension</span>/collapsus, cardiomyopathie de stress ; <br><strong>Musculaire :</strong> rhabdomyolyse → <span class=\"kw-def\">IRA</span> par <span class=\"kw-clinique\">nécrose</span> tubulaire ; <br><strong>Métabolique :</strong> hyperlactatémie (apnée tonique), <span class=\"kw-clinique\">hyperthermie</span>.</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Ce qu'il faut retenir absolument.</strong> Toute crise <span class=\"kw-chiffre\">&gt; 5 min</span> ou toute répétition de crises <span class=\"kw-clinique\">sans reprise de conscience intercritique</span> = EMETCG → appel <span class=\"kw-alerte\">SAMU</span> + BZD IV/IR immédiate (cf. obj-10). Ne JAMAIS attendre la fin spontanée d'une crise prolongée. <span class=\"kw-alerte\">Le temps est neurone.</span>\n      </div>\n\n      <h5>Indications de l'<span class=\"kw-imagerie\">EEG</span> en <span class=\"kw-alerte\">urgence</span> dans l'EME</h5>\n      <p>L'<span class=\"kw-imagerie\">EEG</span> <span class=\"kw-clinique\">n'est pas systématique</span> (diagnostic clinique). Il est indiqué en <span class=\"kw-alerte\">urgence</span> dans 3 situations précises :</p>\n      <table >\n        <thead><tr><th>Indication</th><th>Objectif</th></tr></thead>\n        <tbody>\n          <tr><td><b>EME réfractaire</b></td><td>Dès que possible — <span class=\"kw-clinique\">contrôle de l'efficacité du traitement</span>.</td></tr>\n          <tr><td><b>Suspicion d'EME larvé</b></td><td><span class=\"kw-clinique\">Coma persistant <span class=\"kw-chiffre\">&gt; 30 min</span></span> après l'arrêt clinique des crises → confirmer ou éliminer la persistance d'activité épileptique.</td></tr>\n          <tr><td><b>Doute avec un DD</b></td><td><span class=\"kw-clinique\">Crise non épileptique psychogène</span> (CNEP) — l'<span class=\"kw-imagerie\">EEG</span> sépare crise vraie / crise fonctionnelle.</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Piège PL.</strong> Une <span class=\"kw-bio\">pléïocytose modérée (jusqu'à 20-30 éléments/mL)</span> et une <span class=\"kw-bio\">hyperprotéinorachie modérée &lt; 1 g/L</span> peuvent être <i>expliquées par l'EME lui-même</i>. Ne pas conclure trop vite à une <span class=\"kw-def\">méningo-encéphalite</span> sur ces anomalies seules — confronter à la clinique, à la <span class=\"kw-bio\">PCR HSV</span> et à l'imagerie.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 343 — Etat confusionnel - trouble de conscience</em></p>","frequence":0},{"id":"105-14","rang":"A","rubrique":"Diagnostic positif","titre":"Épilepsies de l'enfant : reconnaître le syndrome de West (spasmes infantiles) de l'enfant","contenu":"<p><span class=\"kw-def\">Syndrome de West</span> = <span class=\"kw-def\">encéphalopathie épileptique</span> du nourrisson liée à l'âge, <span class=\"kw-alerte\">grave et de pronostic réservé</span>. Début entre <span class=\"kw-chiffre\">3 et 12 mois</span> (pic <span class=\"kw-chiffre\">~6 mois</span>). Sex-ratio M ≈ F. <span class=\"kw-def\">Incidence</span> <span class=\"kw-chiffre\">~1/3 000 naissances</span>.</p>\n\n      <h5>Triade diagnostique ⭐ (à connaître par cœur)</h5>\n\n      <table >\n        <thead><tr><th>Élément</th><th>Sémiologie</th></tr></thead>\n        <tbody>\n          <tr><td><b>Spasmes en flexion</b></td><td><strong>Sémiologie :</strong> contraction brusque, brève <span class=\"kw-chiffre\">(1-2 s)</span>, bilatérale, symétrique, en flexion (tête + tronc + bras \"salaam attack\") ou en extension ; <br><strong>Particularité :</strong> survenue <span class=\"kw-clinique\">en salves</span> de <span class=\"kw-chiffre\">10 à 100 spasmes</span> consécutifs ; <br><strong>Horaire :</strong> au <span class=\"kw-clinique\">réveil</span> ou à l'endormissement préférentiellement.</td></tr>\n          <tr><td><b>Régression psychomotrice</b></td><td><strong>Clinique :</strong> <span class=\"kw-clinique\">arrêt ou recul des acquisitions</span> (perte du sourire-réponse, du soutien céphalique, de la poursuite oculaire) ; <br><strong>Évaluation :</strong> bilan développemental précis, comparaison à l'avant-crise.</td></tr>\n          <tr><td><b>Hypsarythmie <span class=\"kw-imagerie\">EEG</span></b></td><td><strong><span class=\"kw-bio\">EEG</span> :</strong> tracé <span class=\"kw-bio\">chaotique de grande amplitude</span>, ondes lentes et pointes asynchrones, désorganisé en permanence ; <br><strong>Particularité :</strong> tracé <span class=\"kw-bio\">pathognomonique</span> du syndrome.</td></tr>\n        </tbody>\n      </table>\n\n      <h5>Étiologies</h5>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Exemples</th></tr></thead>\n        <tbody>\n          <tr><td><b>Structurelle / périnatale</b></td><td><strong>Anoxie :</strong> anoxo-ischémie périnatale ; <br><strong>Malformative :</strong> dysplasie corticale, lissencéphalie, agénésie du corps calleux ; <br><strong>Phacomatose :</strong> <span class=\"kw-etio\">sclérose tubéreuse de Bourneville</span> (cause majeure).</td></tr>\n          <tr><td><b><span class=\"kw-etio\">Génétique</span></b></td><td><strong>Chromosomique :</strong> trisomie 21 ; <br><strong>Monogénique :</strong> mutations ARX, CDKL5, STXBP1.</td></tr>\n          <tr><td><b>Métabolique</b></td><td>Maladies mitochondriales, déficit en pyridoxine (vit B6), aciduries organiques.</td></tr>\n          <tr><td><b>Idiopathique / inconnue</b></td><td>~<span class=\"kw-chiffre\">10-20 %</span> des cas (<span class=\"kw-def\">pronostic</span> globalement plus favorable).</td></tr>\n        </tbody>\n      </table>\n\n      <h5>Prise en charge & <span class=\"kw-def\">pronostic</span></h5>\n      <p><strong>Traitement :</strong> <span class=\"kw-ttt\">vigabatrin</span> en 1<sup>re</sup> intention (surtout si <span class=\"kw-etio\">sclérose tubéreuse de Bourneville</span>) ± <span class=\"kw-ttt\">corticothérapie (ACTH ou prednisolone)</span>. <strong><span class=\"kw-def\">Pronostic</span> :</strong> <span class=\"kw-alerte\">sévère</span> — <span class=\"kw-alerte\">déficit intellectuel ~80 %</span>, <span class=\"kw-clinique\">évolution</span> fréquente vers d'autres syndromes épileptiques (<span class=\"kw-etio\">Lennox-Gastaut</span>). La <span class=\"kw-clinique\">rapidité du diagnostic</span> conditionne le pronostic cognitif.</p>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> Les spasmes sont souvent confondus avec des <span class=\"kw-clinique\">coliques du nourrisson</span> ou un <span class=\"kw-clinique\">réflexe de Moro</span> par les parents → retard diagnostique fréquent (médian <span class=\"kw-chiffre\">1-2 mois</span>). Toute série de spasmes stéréotypés en salves chez un nourrisson de <span class=\"kw-chiffre\">3-12 mois</span> doit faire <span class=\"kw-alerte\">demander un EEG en urgence</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 47 — <span class=\"kw-def\">Suivi</span> d'un nourrisson, d'un enfant, d'un adolescent · 56 — Enfant handicapé</em></p>","frequence":0,"liens":[{"href":"https://infantilespasms.org","label":"Infantile Spasms (ressource patients)"}]},{"id":"105-15","rang":"A","rubrique":"Diagnostic positif","titre":"Épilepsies de l'enfant : reconnaître l'épilepsie absence de l'enfant","contenu":"<p><span class=\"kw-def\">Épilepsie-absence de l'enfant (EAE)</span> = <span class=\"kw-def\">épilepsie</span> généralisée idiopathique (<span class=\"kw-etio\">génétique</span> présumée), parmi les plus fréquentes. Début entre <span class=\"kw-chiffre\">5 et 7 ans</span> (pic <span class=\"kw-chiffre\">6-8 ans</span>), prédominance féminine (F &gt; M), ATCD familiaux fréquents. <span class=\"kw-clinique\">Pronostic globalement favorable</span> (pharmacosensibilité <span class=\"kw-chiffre\">80 %</span>).</p>\n\n      <h5>Sémiologie de l'absence typique</h5>\n      <table >\n        <thead><tr><th>Caractéristique</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><b>Début</b></td><td>Brutal, sans prodrome.</td></tr>\n          <tr><td><b>Sémiologie</b></td><td><strong>Conscience :</strong> <span class=\"kw-alerte\">rupture</span> complète et brève (regard fixe, suspension de l'activité) ; <br><strong>Motricité :</strong> possibles automatismes oraux (mâchonnements, clignements palpébraux) ; <br><strong>Tonus :</strong> pas de chute (sauf forme atonique).</td></tr>\n          <tr><td><b>Durée</b></td><td><span class=\"kw-chiffre\">10-20 secondes</span> typiquement.</td></tr>\n          <tr><td><b>Fréquence</b></td><td><span class=\"kw-clinique\">Très fréquentes</span> : plusieurs dizaines par jour si non traité (impact scolaire majeur).</td></tr>\n          <tr><td><b>Fin</b></td><td>Brutale, <span class=\"kw-clinique\">reprise immédiate de l'activité</span> sans <span class=\"kw-clinique\">confusion</span> post-critique.</td></tr>\n          <tr><td><b>Déclencheur</b></td><td><strong>Hyperpnée</strong> (<span class=\"kw-chiffre\">3 min</span> de respiration profonde) déclenche quasi-constamment une absence — manœuvre diagnostique en consultation et lors de l'<span class=\"kw-imagerie\">EEG</span>.</td></tr>\n        </tbody>\n      </table>\n\n      <h5><span class=\"kw-imagerie\">EEG</span> (élément central du diagnostic)</h5>\n      <p><strong>Tracé intercritique :</strong> souvent <span class=\"kw-clinique\">normal</span> ou rares anomalies. <strong>Tracé critique :</strong> <span class=\"kw-bio\">décharges de pointes-ondes généralisées à 3 Hz</span>, bilatérales, symétriques, synchrones, à début et fin brusques. <strong>Hyperpnée :</strong> déclenche typiquement une absence visible cliniquement + sur l'<span class=\"kw-imagerie\">EEG</span>.</p>\n\n      <h5>Traitement & <span class=\"kw-def\">pronostic</span></h5>\n      <p><strong>1<sup>re</sup> intention :</strong> <span class=\"kw-ttt\">éthosuximide</span> OU <span class=\"kw-ttt\">valproate</span> (attention chez la fille en âge de procréer à venir) OU <span class=\"kw-ttt\">lamotrigine</span>. <strong>À éviter :</strong> <span class=\"kw-ci\">carbamazépine et phénytoïne</span> (peuvent aggraver les absences). <strong><span class=\"kw-def\">Pronostic</span> :</strong> rémission complète chez <span class=\"kw-chiffre\">~80 %</span> des enfants à l'adolescence ; risque de basculer vers une <span class=\"kw-def\">épilepsie</span> myoclonique juvénile ou EGTC dans <span class=\"kw-chiffre\">10-20 %</span> des cas.</p>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège annales.</strong> L'<span class=\"kw-imagerie\">IRM</span> cérébrale n'est <span class=\"kw-clinique\">PAS systématique</span> dans une EAE typique avec sémiologie + <span class=\"kw-imagerie\">EEG</span> concordants (syndrome d'origine <span class=\"kw-etio\">génétique</span> précis). C'est l'une des rares situations où elle peut être omise (cf. obj-3). ⭐\n      </div>","frequence":0}],"astuces":[{"type":"danger","titre":"EME = 5 minutes = clonazépam IV (pas une minute à perdre)","contenu":"Toute crise tonico-clonique qui dure > 5 min doit être traitée comme un EME : clonazépam 1 mg IVL chez l'adulte (0,05 mg/kg enfant) ou diazépam 0,5 mg/kg IR chez l'enfant à domicile. Deuxième dose à T+5 si persistance, puis lévétiracétam 60 mg/kg à T+10. Mortalité 15-20 %, séquelles neurologiques au-delà de 30 min."},{"type":"danger","titre":"Valproate formellement contre-indiqué chez la femme en âge de procréer","contenu":"Tératogénicité majeure (spina bifida, malformations) ET troubles neurodéveloppementaux (QI -7 à -10 points, autisme x5). Carnet et accord de soins obligatoires (programme PRAC). Préférer lamotrigine ou lévétiracétam. Acide folique 5 mg/j dès le projet de grossesse. Cette règle tombe à chaque DP gynéco-neuro."},{"type":"warn","titre":"Morsure latérale de langue = épilepsie ; morsure médiane = syncope","contenu":"La morsure latérale (rebord de la langue) est très spécifique d'une crise tonico-clonique. La morsure médiane ou de la pointe évoque une syncope convulsivante. Toujours examiner la langue après une 'crise' inaugurale et faire ECG + Holter si doute (sténose aortique, QT long, BAV peuvent mimer une épilepsie)."},{"type":"warn","titre":"Crise focale chez le nourrisson fébrile = encéphalite herpétique JPDC","contenu":"Une convulsion fébrile focale, prolongée (> 15 min) ou avec déficit post-critique chez un enfant < 3 ans n'est PAS une CF simple. PL en urgence, IRM, EEG, et aciclovir IV empirique (15 mg/kg/8h) en attendant la PCR HSV. Le retard de l'aciclovir est la 1re cause de séquelles évitables."},{"type":"tip","titre":"Carbamazépine aggrave les absences et les myoclonies","contenu":"Carbamazépine, oxcarbazépine, vigabatrin, gabapentine, phénytoïne sont CONTRE-INDIQUÉS dans les épilepsies généralisées idiopathiques (EAE, EMJ) car ils peuvent aggraver les absences et les myoclonies. Choix de référence : valproate (sauf femme jeune) ou éthosuximide (absences pures) ou lamotrigine/lévétiracétam."},{"type":"info","titre":"Permis de conduire : 1 an sans crise (groupe 1), 10 ans (groupe 2)","contenu":"Arrêté du 28/03/2022 : groupe 1 (VL) = reprise après 1 an sans crise ; groupe 2 (PL, transports) = 10 ans sans crise ET sans traitement. Information du patient = obligation déontologique du médecin ; déclaration à la préfecture = obligation du patient. À mentionner à chaque consultation initiale."}],"strategie":{"urgence":"<p><strong>Degré</strong></p><ul><li>l’<span class=\"kw-def\">état de mal épileptique (EME)</span> est une <span class=\"kw-alerte\">urgence vitale</span></li><li>toute crise <span class=\"kw-chiffre\">≥ 5 min</span> ou crises subintrantes sans reprise de conscience en relèvent</li></ul><p><strong>Délais</strong></p><ul><li>faire cesser la crise le plus tôt possible</li><li><span class=\"kw-alerte\">pronostic vital</span> et fonctionnel engagé au-delà de <span class=\"kw-chiffre\">30 min</span> (<span class=\"kw-def\">mortalité</span> <span class=\"kw-chiffre\">10-20 %</span>)</li></ul><p><strong>Spécificités</strong></p><ul><li>l’EME est la <em>seule</em> indication d’un <span class=\"kw-ttt\">antiépileptique IV en urgence</span></li><li>la <em>seule</em> indication d’<span class=\"kw-bio\">EEG en urgence</span></li></ul>","hospit":"<p><strong>Pas d’hospit :</strong> patient <span class=\"kw-def\">épileptique connu et traité</span> après une crise habituelle ; <span class=\"kw-def\">crise fébrile simple</span> de l’enfant (<span class=\"kw-def\">surveillance</span> <span class=\"kw-chiffre\">4 h</span> si <span class=\"kw-chiffre\">&lt; 12 mois</span>).<br><strong><span class=\"kw-alerte\">SAU</span> (appel 15) :</strong> <span class=\"kw-clinique\">1ʳᵉ crise</span>, crise inhabituelle, ou durée <span class=\"kw-chiffre\">&gt; 5 min</span>.<br><strong>Hospit systématique :</strong> <span class=\"kw-def\">crise fébrile complexe</span> ; avis neuropédiatre selon critères.<br><strong><span class=\"kw-alerte\">Réanimation</span> :</strong> <span class=\"kw-alerte\">EME réfractaire</span> → <span class=\"kw-alerte\">coma</span> thérapeutique + <span class=\"kw-ttt\">intubation</span>.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Crise ≥ 5 min</span> ou <span class=\"kw-alerte\">crises subintrantes</span> sans reprise de conscience (= EME)</li><li><span class=\"kw-alerte\">Troubles de conscience &gt; 30 min</span> après la crise → évoquer un <span class=\"kw-def\">EME larvé</span> (<span class=\"kw-imagerie\">EEG</span>)</li><li><span class=\"kw-alerte\">Déficit focal post-critique durable</span> ou s’aggravant entre 2 examens</li><li><span class=\"kw-alerte\">Détresse respiratoire</span> (apnée, <span class=\"kw-clinique\">cyanose</span>, encombrement) ou <span class=\"kw-alerte\">instabilité hémodynamique</span></li><li><span class=\"kw-clinique\">Fièvre</span> + crise <span class=\"kw-clinique\">focale</span> / <span class=\"kw-chiffre\">&gt; 15 min</span> / répétée → <span class=\"kw-etio\">infection du SNC</span> (<span class=\"kw-alerte\">méningite</span>, <span class=\"kw-alerte\">encéphalite</span> herpétique)</li><li><span class=\"kw-alerte\">Purpura</span> ou <span class=\"kw-clinique\">syndrome méningé</span></li><li>Nourrisson : <span class=\"kw-clinique\">fontanelle bombante</span>, <span class=\"kw-etio\">contexte de maltraitance</span> (hématomes)</li></ul>","principes":"<p><strong>Règle d’or :</strong> <span class=\"kw-alerte\">aucun antiépileptique systématique</span> après une 1ʳᵉ crise isolée (pas même temporaire, BZD comprises).</p><ul><li><span class=\"kw-ttt\">AE de fond</span> seulement si <span class=\"kw-def\">épilepsie</span> diagnostiquée / risque de récidive <span class=\"kw-chiffre\">&gt; 60 % à 10 ans</span></li><li><span class=\"kw-ttt\">Monothérapie</span> à <span class=\"kw-chiffre\">dose minimale efficace</span>, introduction progressive ; <span class=\"kw-ci\">jamais d’arrêt brutal</span> (risque d’EME)</li><li><span class=\"kw-ttt\">Traitement étiologique</span> des causes réversibles : <span class=\"kw-ttt\">G30 %</span> (hypoglycémie), <span class=\"kw-ttt\">NaCl 4,5 %</span> (hyponatrémie), <span class=\"kw-ttt\">sulfate de Mg</span>, <span class=\"kw-ttt\">vitamine B1</span> (alcool / dénutrition / <span class=\"kw-ci\">grossesse</span>)</li><li>EME adulte : <span class=\"kw-ttt\">clonazépam</span> <span class=\"kw-chiffre\">0,015 mg/kg IVD</span> (max <span class=\"kw-chiffre\">1,5 mg</span>), répété, puis AE de 2ᵉ ligne IV</li><li>EME enfant : <span class=\"kw-ttt\">diazépam</span> <span class=\"kw-chiffre\">0,5 mg/kg intra-rectal</span> si crise <span class=\"kw-chiffre\">&gt; 5 min</span></li></ul>","suivi":"<p><strong>Observance :</strong> 1ʳᵉ cause de <span class=\"kw-clinique\">persistance des crises</span> ; <span class=\"kw-ci\">jamais d’arrêt brutal</span> du traitement.<br><strong><span class=\"kw-ttt\">RHD</span> :</strong> <span class=\"kw-clinique\">sommeil régulier</span> ; éviter <span class=\"kw-etio\">alcool</span>, <span class=\"kw-etio\">drogues</span>, excès d’excitants ; si <span class=\"kw-def\">photosensibilité</span>, limiter écrans / lumières stroboscopiques.<br><strong>Conduite :</strong> aptitude décidée par un <span class=\"kw-def\">médecin agréé de la préfecture</span> (<em>pas</em> le médecin traitant) ; permis B après <span class=\"kw-chiffre\">1 an sans crise</span>.<br><strong>Activités interdites :</strong> plongée, escalade sans sécurité, tir sportif, parachute ; pro : port d’armes, chauffeur, surveillant de baignade, bâtiment.<br><strong>Femme :</strong> <span class=\"kw-ttt\">acide folique</span> <span class=\"kw-chiffre\">3 mois avant</span> + 1ᵉ trimestre ; éviter le <span class=\"kw-ci\">valproate</span> (<span class=\"kw-ci\">tératogène</span>) ; les inducteurs enzymatiques ↓ l’efficacité des <span class=\"kw-ttt\">œstroprogestatifs</span>.<br><strong>Enfant :</strong> contrôle à <span class=\"kw-chiffre\">1-2 mois</span> puis <span class=\"kw-chiffre\">tous les 6 mois</span> ; <em>pas</em> de <span class=\"kw-def\">surveillance</span> <span class=\"kw-bio\">EEG</span> / <span class=\"kw-imagerie\">imagerie</span> systématique.</p>"},"liensGlobaux":[{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/neurologie/convulsions-crises-depilepsie-epilepsie","label":"Collège Pédiatrie — Convulsions & épilepsies"},{"href":"https://www.cen-neurologie.fr/second-cycle/epilepsies-de-lenfant-et-de-ladulte","label":"Collège CEN — Épilepsies enfant/adulte"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Première crise convulsive — Après avoir confirmé qu’il s’agit bien d’une crise épileptique (interrogatoire)","detail":"<h4>CAT — première crise convulsive — Orientation diagnostique (adulte & enfant)</h4>","branches":[{"to":"t-eme","label":"État de mal : crise ≥ 5 min ou crises subintrantes sans reprise de conscience","color":"red"},{"to":"q-febrile","label":"Fièvre (enfant 6 mois – 5 ans)","color":"amber"},{"to":"t-provoquee","label":"Pas de fièvre — cause aiguë symptomatique retrouvée","color":"blue"},{"to":"t-non-provoquee","label":"Pas de fièvre — crise non provoquée (bilan négatif)","color":"amber"}]},{"id":"t-eme","kind":"terminal","label":"État de mal épileptique — urgence vitale","color":"red","detail":"<h4>Conduite immédiate</h4><ul><li><span class=\"kw-ttt\">PLS</span>, libération des VAS, noter l’heure de début</li><li>2 <span class=\"kw-ttt\">VVP</span>, <span class=\"kw-ttt\">O₂</span>, monitorage, <span class=\"kw-bio\">glycémie</span> capillaire</li><li><span class=\"kw-ttt\">Clonazépam</span> <span class=\"kw-chiffre\">0,015 mg/kg IVD</span> puis protocole par paliers</li></ul><h4>Renvoi</h4><ul><li>Voir l’<strong>Arbre 2 — CAT thérapeutique de l’<span class=\"kw-alerte\">état de mal</span></strong> ci-dessous</li></ul>"},{"id":"q-febrile","kind":"decision","label":"<span class=\"kw-def\">Critères de</span> complexité de la crise fébrile ? — < 1 an · focale · ><span class=\"kw-chiffre\"> 15 min</span> · répétée sur <span class=\"kw-chiffre\">24 h</span> · déficit post-critique · examen neuro anormal","branches":[{"to":"t-cf-simple","label":"Aucun critère","color":"green"},{"to":"t-cf-complexe","label":"≥ 1 critère","color":"amber"}]},{"id":"t-cf-simple","kind":"terminal","label":"Crise fébrile simple","color":"green","detail":"<h4>Critères</h4><ul><li><span class=\"kw-chiffre\">1 – 5 ans</span>, généralisée, brève <span class=\"kw-chiffre\">&lt; 15 min</span>, 1 seul épisode /<span class=\"kw-chiffre\"> 24 h</span></li><li>Examen neuro normal, pas de déficit post-critique</li></ul><h4>PEC</h4><ul><li><span class=\"kw-alerte\">Aucun bilan</span> complémentaire, rassurer les parents</li><li>Antipyrétiques ; <span class=\"kw-ttt\">diazépam intra-rectal</span> si récidive <span class=\"kw-chiffre\">&gt; 5 min</span></li></ul><h4>Renvoi</h4><ul><li>Item 346 (Convulsions du nourrisson/enfant)</li></ul>"},{"id":"t-cf-complexe","kind":"terminal","label":"Crise fébrile complexe","color":"amber","detail":"<h4>Bilan</h4><ul><li><span class=\"kw-ttt\">PL</span> si <span class=\"kw-chiffre\">&lt; 6 mois</span> ou suspicion d’<span class=\"kw-etio\">infection du SNC</span></li><li><span class=\"kw-imagerie\">TDM</span> / <span class=\"kw-bio\">EEG</span> selon le contexte</li></ul><h4>PEC</h4><ul><li><span class=\"kw-alerte\">Hospitalisation systématique</span>, avis neuropédiatre</li><li>Recherche d’une cause à la <span class=\"kw-clinique\">fièvre</span></li></ul><h4>Renvoi</h4><ul><li>Item 151 (Méningite) · Item 346</li></ul>"},{"id":"t-provoquee","kind":"terminal","label":"Crise symptomatique aiguë (provoquée)","color":"blue","detail":"<h4>Définition</h4><ul><li>Crise survenant <span class=\"kw-chiffre\">&lt; 7 jours</span> d’une agression cérébrale aiguë</li></ul><h4>Causes</h4><ul><li><span class=\"kw-etio\">Métabolique</span> : hypoglycémie, hyponatrémie, hypocalcémie</li><li><span class=\"kw-etio\">Toxique</span> : <span class=\"kw-ttt\">sevrage</span> alcool/BZD, médicaments épileptogènes</li><li><span class=\"kw-etio\">Vasculaire</span> : <span class=\"kw-alerte\">AVC</span>, hémorragie méningée</li><li><span class=\"kw-etio\">Infectieuse</span> : méningo-encéphalite</li><li><span class=\"kw-etio\">Traumatique</span> : TC récent</li></ul><h4>PEC</h4><ul><li><span class=\"kw-ttt\">Traiter la cause</span> ; <span class=\"kw-alerte\">pas d’antiépileptique de fond</span></li></ul><h4>Renvois</h4><ul><li>Items 240 · 267 · 340 · 341 · 151 · 74</li></ul>"},{"id":"t-non-provoquee","kind":"terminal","label":"Crise non provoquée → bilan d’épilepsie","color":"amber","detail":"<h4>Bilan</h4><ul><li><span class=\"kw-bio\">EEG</span> dans les <span class=\"kw-chiffre\">&lt; 24 h</span> (contribue au dg positif ; normal n’exclut pas)</li><li><span class=\"kw-imagerie\">IRM cérébrale</span> systématique sauf syndrome <span class=\"kw-etio\">génétique</span> précis</li></ul><h4>Risque de récidive</h4><ul><li>Élevé (<span class=\"kw-chiffre\">&gt; 60 % / 10 ans</span>) si : anomalies paroxystiques <span class=\"kw-bio\">EEG</span>, <span class=\"kw-clinique\">lésion</span> épileptogène à l’<span class=\"kw-imagerie\">imagerie</span>, trouble neurodéveloppemental</li></ul><h4>Décision</h4><ul><li><span class=\"kw-ttt\">AE de fond</span> uniquement si épilepsie diagnostiquée / haut risque de récidive</li></ul>"}]},"cards":[{"i":"0b4230469632","n":105,"o":"105-1","u":"Définition","t":"Définir la crise d'épilepsie et la maladie épileptique","q":"Quels sont les trois critères ILAE permettant de poser le diagnostic de maladie épileptique ?","a":"<ul><li>La survenue d'<strong>au moins 2 crises non provoquées</strong>, espacées de <strong>plus de 24 heures</strong>, cliniquement avérées.</li><li>La survenue d'<strong>une seule crise non provoquée</strong>, associée à un risque de récidive <strong>> 60 % à 10 ans</strong> (suite à la présence d'anomalies EEG, d'une lésion épileptogène à l'imagerie ou d'un trouble neurodéveloppemental préexistant).</li><li>L'identification d'un <strong>syndrome épileptique</strong> spécifique selon la classification ILAE.</li></ul>"},{"i":"368a3659d88e","n":105,"o":"105-1","u":"Définition","t":"Définir la crise d'épilepsie et la maladie épileptique","q":"Est-ce que deux crises provoquées (ex. sevrage alcoolique) définissent une maladie épileptique ?","a":"<p><strong>Non</strong>, deux crises provoquées (par exemple, lors d'un sevrage en alcool ou d'une hypoglycémie) ne définissent <strong>pas</strong> une maladie épileptique. Ce sont des crises symptomatiques aiguës.</p>"},{"i":"7c62bf3b896f","n":105,"o":"105-1","u":"Définition","t":"Définir la crise d'épilepsie et la maladie épileptique","q":"Quelle est la définition d'une crise d'épilepsie ?","a":"<p>Une crise d'épilepsie est une <strong>manifestation clinique paroxystique</strong> (motrice, sensitive, sensorielle, végétative ou psychique) liée à une <strong>décharge anormale, excessive et hypersynchrone</strong> d'une population neuronale corticale. La sémiologie reflète la topographie de la décharge et est souvent stéréotypée chez un même malade.</p>"},{"i":"9021b14e6717","n":105,"o":"105-1","u":"Définition","t":"Définir la crise d'épilepsie et la maladie épileptique","q":"Comment définit-on la maladie épileptique ?","a":"<p>La maladie épileptique est une <strong>prédisposition cérébrale durable</strong> à générer des crises. Le diagnostic est posé lorsque l'un des trois critères de l'ILAE est rempli.</p>"},{"i":"c30fa593747c","n":105,"o":"105-1","u":"Définition","t":"Définir la crise d'épilepsie et la maladie épileptique","q":"Quand une crise unique non provoquée ne permet-elle pas de diagnostiquer une maladie épileptique ?","a":"<p>Une crise unique non provoquée n'autorise <strong>pas</strong> le diagnostic de maladie épileptique s'il n'existe <strong>pas de critère de prédisposition durable</strong> (comme une anomalie EEG, une lésion ou un trouble neurodéveloppemental).</p>"},{"i":"3803c7f28411","n":105,"o":"105-10","u":"Prise en charge","t":"Connaître la conduite à tenir en présence d'une crise généralisée tonico-clonique","q":"Quelles sont les mesures à prendre pendant la phase résolutive d'une crise généralisée tonico-clonique (CGTC) ?","a":"<p>Pendant la phase résolutive d'une CGTC, il faut :</p><ul><li>Placer le patient en <strong>Position Latérale de Sécurité (PLS)</strong>.</li><li>Assurer la <strong>liberté des voies aériennes supérieures (VAS)</strong> par aspiration des sécrétions et éventuellement l'insertion d'une canule oropharyngée (de Guedel).</li><li>Administrer de l'<strong>oxygénothérapie</strong> au masque à haute concentration, idéalement à <strong>10 L/min</strong>.</li><li>Poser <strong>deux voies veineuses périphériques (VVP)</strong> et initier un remplissage avec <strong>1 litre de NaCl 0,9 %</strong>.</li><li>Réaliser une <strong>glycémie capillaire systématique</strong> (et resucrer si hypoglycémie).</li></ul>"},{"i":"6803a35b8700","n":105,"o":"105-10","u":"Prise en charge","t":"Connaître la conduite à tenir en présence d'une crise généralisée tonico-clonique","q":"Quel bilan paraclinique est à réaliser après une première crise généralisée tonico-clonique ?","a":"<p>Après une première crise généralisée tonico-clonique, le bilan paraclinique comprend :</p><ul><li><strong>Biologie</strong> : glycémie, ionogramme sanguin (avec calcémie et magnésémie), urée/créatinine, bilan hépatique, ammoniémie, hémostase, CRP, β-hCG (chez la femme), et éventuellement toxiques, alcool, benzodiazépines, HbCO.</li><li><strong>Électroencéphalogramme (EEG)</strong> : à réaliser dans les <strong>24 heures</strong> (seul examen contribuant au diagnostic positif, mais un EEG normal n'exclut pas le diagnostic d'épilepsie). L'EEG en urgence est indiqué seulement en cas de suspicion d'État de Mal Épileptique.</li><li><strong>Imagerie cérébrale</strong> : TDM ou IRM cérébrale.</li><li><strong>Électrocardiogramme (ECG)</strong> : systématique pour éliminer une cause cardiaque.</li></ul>"},{"i":"e6d89be2cfac","n":105,"o":"105-10","u":"Prise en charge","t":"Connaître la conduite à tenir en présence d'une crise généralisée tonico-clonique","q":"Quelle est la première étape de la conduite à tenir immédiate face à une crise généralisée tonico-clonique (CGTC) ?","a":"<p>La première étape est de <strong>sécuriser l'environnement</strong> du patient :</p><ul><li>Dégager les objets dangereux et éloigner le mobilier.</li><li>Protéger la tête du patient avec un coussin ou les mains pour éviter les traumatismes.</li><li>NE PAS introduire d'objet dans la bouche.</li><li>NE PAS contraindre les mouvements.</li></ul>"},{"i":"ed9322565c5d","n":105,"o":"105-10","u":"Prise en charge","t":"Connaître la conduite à tenir en présence d'une crise généralisée tonico-clonique","q":"Comment apprécier et gérer la durée d'une crise généralisée tonico-clonique (CGTC) pour évaluer son urgence ?","a":"<p>Il est crucial d'<strong>observer et de chronométrer la durée</strong> de la crise. Cela permet de distinguer :</p><ul><li>Une crise isolée, qui cède spontanément <strong>en moins de 5 minutes</strong>, et nécessite une surveillance avec bilan différé.</li><li>Un État de Mal Épileptique Tonico-Clonique Généralisé (EMETCG), si la crise <strong>dépasse 5 minutes</strong> ou se répète sans reprise de conscience, nécessitant l'administration de <strong>benzodiazépines IV/IR</strong> et l'appel au SAMU.</li></ul>"},{"i":"98719cdf407d","n":105,"o":"105-12","u":"Prise en charge","t":"Connaître les principaux conseils concernant la vie quotidienne chez un patient épileptique","q":"Quels sont les conseils d'hygiène de vie essentiels pour un patient épileptique afin d'éviter les facteurs précipitants ?","a":"<p>Pour un patient épileptique, les conseils d'hygiène de vie incluent :</p><ul><li><strong>Sommeil</strong> : régularité, au moins <strong>7-8 heures</strong> par nuit, et éviter les nuits blanches (dette de sommeil est un facteur précipitant majeur).</li><li><strong>Alcool</strong> : consommation modérée, jamais d'ivresse, et pas de sevrage brutal.</li><li><strong>Drogues</strong> : cocaïne, héroïne, cannabis non appauvri en THC sont proscrits.</li><li><strong>Excitants</strong> : limiter café, thé, Coca-Cola caféiné.</li><li><strong>Plantes</strong> : éviter sauge, thym, eucalyptus (huiles essentielles) et millepertuis (gélules).</li><li><strong>Écrans</strong> (si photosensibilité) : faire des pauses régulières, maintenir une distance d'au moins <strong>2 mètres</strong> et toujours utiliser les écrans avec une luminosité ambiante allumée.</li></ul>"},{"i":"dc7d5717da0d","n":105,"o":"105-12","u":"Prise en charge","t":"Connaître les principaux conseils concernant la vie quotidienne chez un patient épileptique","q":"Comment les traitements antiépileptiques interagissent-ils avec la contraception, et quels sont les conseils spécifiques pour les femmes en âge de procréer sous valproate ?","a":"<p>Les interactions entre antiépileptiques et contraception nécessitent une attention particulière :</p><ul><li>Les <strong>inducteurs enzymatiques</strong> (carbamazépine, oxcarbazépine, eslicarbazépine, phénytoïne, phénobarbital) réduisent l'efficacité des <strong>œstroprogestatifs</strong>.</li><li>La <strong>COP</strong> (contraception œstroprogestative) peut diminuer l'efficacité de la <strong>lamotrigine</strong>.</li><li>Les alternatives contraceptives sûres incluent les <strong>DIU lévonorgestrel ou DIU cuivre</strong>, et les méthodes de barrière.</li><li>Le <strong>valproate</strong> est <strong>contre-indiqué</strong> chez la femme en âge de procréer en raison d'une tératogénicité majeure et d'un risque de retard cognitif. Il nécessite un <strong>PPP (programme prévention grossesse)</strong> avec un formulaire annuel obligatoire en France depuis 2018.</li></ul><p>Toute prescription d'antiépileptique chez une femme en âge de procréer doit systématiquement inclure un conseil sur la contraception, la supplémentation en <strong>acide folique 5 mg/j</strong> (3 mois avant conception et pendant tout le 1er trimestre pour prévenir les malformations du tube neural), et une information détaillée sur les bénéfices/risques.</p>"},{"i":"e0169ff3189f","n":105,"o":"105-12","u":"Prise en charge","t":"Connaître les principaux conseils concernant la vie quotidienne chez un patient épileptique","q":"Quelles sont les activités professionnelles formellement interdites pour un patient épileptique et quelle est la démarche à suivre en cas de difficulté professionnelle ?","a":"<p>Certaines activités professionnelles sont formellement interdites aux patients épileptiques en raison des risques :</p><ul><li>Port d'armes (militaire, policier, gardien de prison).</li><li>Chauffeur professionnel (PL, bus, ambulance).</li><li>Surveillant de baignade.</li><li>Professions du bâtiment (charpentier, zingueur).</li><li>Travail en hauteur.</li><li>Machines dangereuses non sécurisées.</li></ul><p>En cas de difficulté, un avis de la <strong>médecine du travail</strong> est systématique, et une demande de <strong>RQTH</strong> (reconnaissance de la qualité de travailleur handicapé) peut être instruite en cas d'inaptitude.</p>"},{"i":"f4cbe43c923b","n":105,"o":"105-12","u":"Prise en charge","t":"Connaître les principaux conseils concernant la vie quotidienne chez un patient épileptique","q":"Quels sont les conseils concernant la conduite automobile pour un patient épileptique souhaitant obtenir ou conserver un permis de conduire ?","a":"<p>Pour la conduite automobile chez un patient épileptique :</p><ul><li><strong>Permis B (véhicules légers)</strong> : un délai d'au moins <strong>1 an</strong> sans crise sous traitement est requis. L'avis d'une commission médicale du permis (médecin agréé par la préfecture, pas le médecin traitant) est obligatoire.</li><li><strong>Permis lourd (PL, transport en commun, taxi)</strong> : n'est possible que s'il y a <strong>10 ans</strong> de guérison sans récidive et sans aucun traitement.</li><li><strong>Modification de traitement</strong> : il faut attendre <strong>6 mois</strong> sans crise après un changement de traitement pour pouvoir reprendre la conduite.</li></ul>"},{"i":"282fc47f92ea","n":105,"o":"105-13","u":"Identifier une urgence","t":"Connaître l'urgence vitale de la prise en charge d'un état de mal épileptique","q":"Dans quelles situations l'électroencéphalogramme (EEG) en urgence est-il indiqué lors d'un état de mal épileptique (EME) ?","a":"<p>L'EEG n'est pas systématique, mais il est indiqué en urgence dans <strong>3 situations</strong> :</p><ul><li><strong>EME réfractaire</strong> : pour contrôler l'efficacité du traitement.</li><li><strong>Suspicion d'EME larvé</strong> : devant un coma persistant > 30 min après arrêt clinique des crises, pour confirmer ou éliminer la persistance d'activité épileptique.</li><li><strong>Doute avec un diagnostic différentiel</strong> : notamment une crise non épileptique psychogène (CNEP), pour différencier crise vraie et crise fonctionnelle.</li></ul>"},{"i":"88c6e9c1eb14","n":105,"o":"105-13","u":"Identifier une urgence","t":"Connaître l'urgence vitale de la prise en charge d'un état de mal épileptique","q":"Quel piège diagnostique clinique est à connaître concernant l'analyse du liquide céphalo-rachidien (LCR) lors d'un état de mal épileptique (EME) ?","a":"<p>Un piège est qu'une <strong>pléiocytose modérée</strong> (jusqu'à 20-30 éléments/mL) et une <strong>hyperprotéinorachie modérée</strong> (< 1 g/L) dans le LCR peuvent être expliquées par l'EME lui-même. Il ne faut pas conclure trop vite à une méningo-encéphalite sur ces anomalies seules, mais les confronter à la clinique, à la PCR HSV et à l'imagerie.</p>"},{"i":"9332c8e94905","n":105,"o":"105-13","u":"Identifier une urgence","t":"Connaître l'urgence vitale de la prise en charge d'un état de mal épileptique","q":"Quelles sont les complications systémiques d'un état de mal épileptique (EME) ?","a":"<p>Les complications systémiques d'un EME sont :</p><ul><li><strong>Respiratoires</strong> : apnée tonique, inhalation, OAP.</li><li><strong>Cardiovasculaires</strong> : poussée hypertensive initiale, puis hypotension/collapsus, cardiomyopathie de stress.</li><li><strong>Musculaires</strong> : rhabdomyolyse pouvant entraîner une <strong>IRA par nécrose tubulaire</strong>.</li><li><strong>Métaboliques</strong> : hyperlactatémie, <strong>hyperthermie</strong>.</li></ul>"},{"i":"9a3dc20ef8d2","n":105,"o":"105-13","u":"Identifier une urgence","t":"Connaître l'urgence vitale de la prise en charge d'un état de mal épileptique","q":"Pourquoi un état de mal épileptique (EME) constitue-t-il une urgence vitale absolue ?","a":"<p>L'EME est une urgence vitale absolue car le pronostic vital et fonctionnel se joue dans les <strong>30 premières minutes</strong>. La mortalité atteint <strong>10 à 20%</strong> même avec une prise en charge adaptée, en raison de complications comme la détresse respiratoire, le collapsus, l'arrêt cardiaque ou la cause sous-jacente.</p>"},{"i":"a68affb4284f","n":105,"o":"105-13","u":"Identifier une urgence","t":"Connaître l'urgence vitale de la prise en charge d'un état de mal épileptique","q":"Quels sont les mécanismes de souffrance neuronale et les facteurs aggravants lors d'un état de mal épileptique (EME) ?","a":"<p>La souffrance neuronale est diffuse par <strong>excitotoxicité</strong>. Les facteurs aggravants sont :</p><ul><li><strong>Hypoxie</strong></li><li><strong>Hypotension</strong></li><li><strong>Hypoglycémie</strong></li><li><strong>Acidose lactique</strong></li><li><strong>Fièvre</strong></li></ul><p>Des séquelles potentielles incluent troubles attentionnels, cognitifs, détérioration intellectuelle et aggravation/apparition d'une épilepsie chronique.</p>"},{"i":"0851981896a4","n":105,"o":"105-14","u":"Diagnostic positif","t":"Épilepsies de l'enfant : reconnaître le syndrome de West (spasmes infantiles) de l'enfant","q":"Que signifie la régression psychomotrice dans le contexte du syndrome de West ?","a":"<p>La régression psychomotrice se manifeste par un <strong>arrêt ou un recul des acquisitions</strong> précédemment établies chez le nourrisson. Cela peut inclure la perte du sourire-réponse, du soutien céphalique ou de la poursuite oculaire.</p>"},{"i":"46cb11d063b8","n":105,"o":"105-14","u":"Diagnostic positif","t":"Épilepsies de l'enfant : reconnaître le syndrome de West (spasmes infantiles) de l'enfant","q":"Comment l'électroencéphalogramme (EEG) se présente-t-il typiquement dans le syndrome de West ?","a":"<p>L'EEG dans le syndrome de West révèle une <strong>hypsarythmie</strong>, caractérisée par un tracé <strong>chaotique de grande amplitude</strong>, avec des ondes lentes et des pointes <strong>asynchrones</strong>, le tout étant désorganisé en permanence. C'est un tracé <strong>pathognomonique</strong> du syndrome.</p>"},{"i":"50681492e305","n":105,"o":"105-14","u":"Diagnostic positif","t":"Épilepsies de l'enfant : reconnaître le syndrome de West (spasmes infantiles) de l'enfant","q":"Qu'est-ce que le syndrome de West et quelle est sa période de survenue typique chez le nourrisson ?","a":"<p>Le syndrome de West est une <strong>encéphalopathie épileptique du nourrisson</strong> liée à l'âge, grave et de pronostic réservé.</p><p>Il débute généralement entre <strong>3 et 12 mois</strong>, avec un pic autour de <strong>6 mois</strong>.</p>"},{"i":"61299aeb47d3","n":105,"o":"105-14","u":"Diagnostic positif","t":"Épilepsies de l'enfant : reconnaître le syndrome de West (spasmes infantiles) de l'enfant","q":"Quel est le traitement de première intention du syndrome de West et son pronostic global ?","a":"<p>Le traitement de première intention du syndrome de West est le <strong>vigabatrin</strong>, particulièrement si une sclérose tubéreuse de Bourneville est présente. Une corticothérapie (ACTH ou prednisolone) peut être associée.</p><p>Le pronostic est <strong>sévère</strong>, avec un déficit intellectuel chez environ 80% des enfants et une évolution fréquente vers d'autres syndromes épileptiques comme le <strong>syndrome de Lennox-Gastaut</strong>. La rapidité du diagnostic est cruciale pour le pronostic cognitif.</p>"},{"i":"73014d490a90","n":105,"o":"105-14","u":"Diagnostic positif","t":"Épilepsies de l'enfant : reconnaître le syndrome de West (spasmes infantiles) de l'enfant","q":"Quelle est la triade diagnostique caractéristique du syndrome de West ?","a":"<p>La triade diagnostique du syndrome de West est la suivante :</p><ul><li><strong>Spasmes en flexion</strong> (ou en extension), survenant en salves.</li><li><strong>Régression psychomotrice</strong>.</li><li><strong>Hypsarythmie à l'EEG</strong>.</li></ul>"},{"i":"8ffc02b85d3c","n":105,"o":"105-14","u":"Diagnostic positif","t":"Épilepsies de l'enfant : reconnaître le syndrome de West (spasmes infantiles) de l'enfant","q":"Quel est le piège diagnostique classique lié au syndrome de West et quelle conduite tenir en conséquence ?","a":"<p>Le piège diagnostique classique est la confusion des spasmes avec des <strong>coliques du nourrisson ou un réflexe de Moro</strong> par les parents, entraînant un retard diagnostique fréquent (médian 1-2 mois).</p><p>Toute série de spasmes stéréotypés en salves chez un nourrisson de <strong>3 à 12 mois</strong> doit faire demander un <strong>EEG en urgence</strong>.</p>"},{"i":"c9881958c3e4","n":105,"o":"105-14","u":"Diagnostic positif","t":"Épilepsies de l'enfant : reconnaître le syndrome de West (spasmes infantiles) de l'enfant","q":"Quelles sont les principales catégories étiologiques du syndrome de West ?","a":"<p>Les principales catégories étiologiques du syndrome de West sont :</p><ul><li><strong>Structurelles / périnatales</strong> : anoxie (anoxo-ischémie périnatale), malformations (dysplasie corticale, lissencéphalie), phacomatoses (notamment la <strong>sclérose tubéreuse de Bourneville</strong>).</li><li><strong>Génétiques</strong> : chromosomiques (trisomie 21), monogéniques (mutations ARX, CDKL5).</li><li><strong>Métaboliques</strong> : maladies mitochondriales, déficit en pyridoxine (vitamine B6).</li><li><strong>Idiopathiques / inconnues</strong> : environ 10-20% des cas, avec un pronostic globalement plus favorable.</li></ul>"},{"i":"cce535a7b1c9","n":105,"o":"105-14","u":"Diagnostic positif","t":"Épilepsies de l'enfant : reconnaître le syndrome de West (spasmes infantiles) de l'enfant","q":"Comment se manifestent cliniquement les spasmes dans le syndrome de West ?","a":"<p>Les spasmes sont des contractions brusques, brèves (<strong>1-2 secondes</strong>), bilatérales et symétriques. Ils se manifestent le plus souvent en <strong>flexion</strong> (tête, tronc et bras, type \"salaam attack\"), mais peuvent aussi être en extension.</p><p>Leur particularité est de survenir en <strong>salves de 10 à 100 spasmes</strong> consécutifs, préférentiellement au réveil ou à l'endormissement.</p>"},{"i":"3af2e5d4891e","n":105,"o":"105-15","u":"Diagnostic positif","t":"Épilepsies de l'enfant : reconnaître l'épilepsie absence de l'enfant","q":"Comment définir et caractériser l'épilepsie-absence de l'enfant (EAE) ?","a":"<p>L'épilepsie-absence de l'enfant (EAE) est une forme d'<strong>épilepsie généralisée idiopathique</strong> (d'origine génétique présumée), fréquente, débutant généralement entre <strong>5 et 7 ans</strong> (pic à 6-8 ans), avec une prédominance féminine (F > M). Elle est souvent associée à des antécédents familiaux.</p>"},{"i":"70cbdba468e1","n":105,"o":"105-15","u":"Diagnostic positif","t":"Épilepsies de l'enfant : reconnaître l'épilepsie absence de l'enfant","q":"Quels sont les traitements de première intention de l'épilepsie-absence de l'enfant (EAE) et quels sont les médicaments à éviter ?","a":"<p>Les traitements de première intention de l'EAE sont :</p><ul><li>L'<strong>éthosuximide</strong>.</li><li>Le <strong>valproate</strong> (avec précautions chez la fille en âge de procréer).</li><li>La <strong>lamotrigine</strong>.</li></ul><p>Les médicaments à éviter, car ils peuvent aggraver les absences, sont la <strong>carbamazépine</strong> et la <strong>phénytoïne</strong>.</p>"},{"i":"d46d1167e51e","n":105,"o":"105-15","u":"Diagnostic positif","t":"Épilepsies de l'enfant : reconnaître l'épilepsie absence de l'enfant","q":"Quel est le pronostic de l'épilepsie-absence de l'enfant (EAE) et quel examen n'est généralement pas systématique ?","a":"<p>Le pronostic de l'EAE est globalement favorable, avec une rémission complète chez environ <strong>80 %</strong> des enfants à l'adolescence. Il existe un risque de basculer vers une épilepsie myoclonique juvénile ou des crises tonico-cloniques généralisées (EGTC) dans 10-20 % des cas.</p><p>L'<strong>IRM cérébrale</strong> n'est <strong>PAS systématique</strong> dans une EAE typique, avec une sémiologie et un EEG concordants, car il s'agit d'un syndrome d'origine génétique précis.</p>"},{"i":"d56f3ef0675d","n":105,"o":"105-15","u":"Diagnostic positif","t":"Épilepsies de l'enfant : reconnaître l'épilepsie absence de l'enfant","q":"Quelle est la sémiologie clinique typique d'une absence dans l'épilepsie-absence de l'enfant (EAE) ?","a":"<p>L'absence typique d'une EAE se caractérise par :</p><ul><li>Un début <strong>brutal</strong>, sans prodrome.</li><li>Une rupture complète et brève de la <strong>conscience</strong> avec un regard fixe et une suspension de l'activité.</li><li>De possibles <strong>automatismes oraux</strong> (mâchonnements, clignements palpébraux).</li><li>L'absence de chute (le <strong>tonus est conservé</strong>, sauf formes atoniques).</li><li>Une durée typique de <strong>10-20 secondes</strong>.</li><li>Une fréquence très élevée si non traitée (plusieurs dizaines par jour).</li><li>Une fin <strong>brutale</strong> avec reprise immédiate de l'activité, sans confusion post-critique.</li></ul>"},{"i":"e1154514ac3e","n":105,"o":"105-15","u":"Diagnostic positif","t":"Épilepsies de l'enfant : reconnaître l'épilepsie absence de l'enfant","q":"Comment confirmer le diagnostic d'épilepsie-absence de l'enfant (EAE) par l'EEG ?","a":"<p>L'EEG est un élément central du diagnostic de l'EAE :</p><ul><li>Le tracé intercritique : souvent normal ou avec de rares anomalies.</li><li>Le tracé critique : présence de <strong>décharges de pointes-ondes généralisées à 3 Hz</strong>, bilatérales, symétriques, synchrones, avec un début et une fin brusques.</li><li>Le facteur déclencheur : une <strong>hyperpnée</strong> (3 minutes de respiration profonde) déclenche quasi-constamment une absence visible cliniquement et enregistrée à l'EEG.</li></ul>"},{"i":"35d80b287bde","n":105,"o":"105-3","u":"Définition","t":"Connaître la classification syndromique des crises d'épilepsie et son intérêt pronostique","q":"Selon la classification ILAE 2017, quels sont les trois niveaux successifs permettant de caractériser une épilepsie ?","a":"<p>La classification ILAE 2017 articule les trois niveaux successifs suivants :</p><ul><li>Le <strong>type de crise</strong>.</li><li>Le <strong>type d'épilepsie</strong>.</li><li>Le <strong>syndrome épileptique</strong>.</li></ul>"},{"i":"36285464425d","n":105,"o":"105-3","u":"Définition","t":"Connaître la classification syndromique des crises d'épilepsie et son intérêt pronostique","q":"Quels sont les différents types d'épilepsie selon la classification ILAE 2017 ?","a":"<p>Selon la classification ILAE 2017, les types d'épilepsie sont :</p><ul><li>L'épilepsie <strong>focale</strong>.</li><li>L'épilepsie <strong>généralisée</strong>.</li><li>L'épilepsie <strong>combinée</strong> (à la fois focale et généralisée).</li><li>L'épilepsie de type <strong>inconnu</strong>.</li></ul>"},{"i":"6271faffb86c","n":105,"o":"105-3","u":"Définition","t":"Connaître la classification syndromique des crises d'épilepsie et son intérêt pronostique","q":"Comment les types de crises épileptiques sont-ils définis dans la classification ILAE 2017 ?","a":"<p>Dans la classification ILAE 2017, les types de crises sont définis comme suit :</p><ul><li>La crise <strong>focale</strong> : origine dans une <strong>zone corticale circonscrite</strong>.</li><li>La crise <strong>généralisée</strong> : implique les <strong>deux hémisphères d'emblée</strong>.</li><li>La crise de <strong>début inconnu</strong> : lorsque la sémiologie ou l'EEG sont insuffisants pour la classer.</li></ul>"},{"i":"93ae554484f9","n":105,"o":"105-3","u":"Définition","t":"Connaître la classification syndromique des crises d'épilepsie et son intérêt pronostique","q":"Quel est l'intérêt de la classification syndromique des épilepsies, en particulier au niveau du syndrome épileptique ?","a":"<p>Le syndrome épileptique, qui correspond à un <strong>ensemble cohérent</strong> de crises, de données EEG, d'âge et de comorbidités, est crucial car il <strong>conditionne le pronostic</strong> et le <strong>choix du traitement</strong>. Il permet d'orienter l'évolution naturelle, d'adapter les traitements (par exemple, <strong>valproate</strong> pour un large spectre, <strong>carbamazépine</strong> pour un spectre étroit), de définir la durée de traitement et la guidance familiale.</p>"},{"i":"c997e1dc43b8","n":105,"o":"105-3","u":"Définition","t":"Connaître la classification syndromique des crises d'épilepsie et son intérêt pronostique","q":"Quels sont les axes étiologiques transversaux à considérer dans la classification ILAE 2017 des épilepsies ?","a":"<p>Les axes étiologiques, transversaux aux trois niveaux de classification (type de crise, type d'épilepsie, syndrome épileptique), sont les suivants :</p><ul><li><strong>Structurelle</strong>.</li><li><strong>Génétique</strong>.</li><li><strong>Infectieuse</strong>.</li><li><strong>Métabolique</strong>.</li><li><strong>Dysimmune</strong>.</li><li>De cause <strong>inconnue</strong>.</li></ul>"},{"i":"16b975d35c35","n":105,"o":"105-4","u":"Définition","t":"Définir une épilepsie idiopathique (génétique présumée) et connaître la classification étiologique des épilepsies","q":"Quelle est la définition d'une épilepsie idiopathique (génétique présumée) ?","a":"<p>Une épilepsie idiopathique (génétique présumée) est une épilepsie sans <strong>lésion cérébrale identifiable</strong>, secondaire à une <strong>prédisposition génétique présumée ou prouvée</strong>. Son début est souvent dans l'enfance/adolescence, l'examen neurologique et l'imagerie sont normaux, l'EEG est souvent typique du syndrome, et le pronostic est globalement favorable avec une pharmacosensibilité ≥ 70 %.</p>"},{"i":"23c551d22554","n":105,"o":"105-4","u":"Définition","t":"Définir une épilepsie idiopathique (génétique présumée) et connaître la classification étiologique des épilepsies","q":"Donnez des exemples d'étiologies génétiques des épilepsies, en précisant une nuance importante.","a":"<ul><li><strong>Canalopathies</strong> : mutations <strong>SCN1A</strong> (syndrome de Dravet), GLUT1</li><li><strong>Syndromes</strong> : épilepsie-absence de l'enfant, épilepsie myoclonique juvénile, EGTC du réveil</li></ul><p>Une nuance importante est qu'il n'y a pas de correspondance stricte entre le diagnostic syndromique et génétique ; un même génotype peut correspondre à plusieurs phénotypes (et inversement).</p>"},{"i":"545581bb4bc2","n":105,"o":"105-4","u":"Définition","t":"Définir une épilepsie idiopathique (génétique présumée) et connaître la classification étiologique des épilepsies","q":"Quels sont des exemples d'étiologies structurelles d'épilepsies ?","a":"<ul><li><strong>Vasculaire</strong> : AVC ischémique/hémorragique, MAV, cavernome</li><li><strong>Tumorale</strong> : gliome, méningiome, métastase</li><li><strong>Traumatique</strong> : séquelle post-TC, hématome sous-dural chronique (HSD)</li><li><strong>Malformative</strong> : dysplasie corticale focale, hétérotopie, sclérose hippocampique</li></ul>"},{"i":"74e9d9e82aca","n":105,"o":"105-4","u":"Définition","t":"Définir une épilepsie idiopathique (génétique présumée) et connaître la classification étiologique des épilepsies","q":"Quand l'IRM cérébrale n'est-elle PAS systématique devant une épilepsie ?","a":"<p>L'IRM cérébrale n'est <strong>PAS systématique</strong> si un syndrome d'origine génétique précis est suspecté cliniquement et confirmé par un EEG typique (par exemple, l'épilepsie-absence de l'enfant).</p>"},{"i":"85387dfe4a56","n":105,"o":"105-4","u":"Définition","t":"Définir une épilepsie idiopathique (génétique présumée) et connaître la classification étiologique des épilepsies","q":"Quelles sont les six catégories étiologiques des épilepsies selon la classification ILAE 2017 ?","a":"<ul><li><strong>Structurelle</strong></li><li><strong>Génétique</strong></li><li><strong>Infectieuse</strong></li><li><strong>Métabolique</strong></li><li><strong>Dysimmune</strong></li><li><strong>Inconnue</strong></li></ul>"},{"i":"12862c01d152","n":105,"o":"105-6","u":"Etiologies","t":"Connaître les principales causes d'épilepsies","q":"Quelles sont les principales causes métaboliques de crises symptomatiques aiguës ?","a":"<ul><li><strong>Glycémie</strong> : Hypoglycémie, hyperglycémie.</li><li><strong>Calcémie</strong> : Hypo- et hypercalcémie.</li><li><strong>Natrémie</strong> : Hypo- et hypernatrémie.</li><li><strong>Magnésémie</strong> : Hypomagnésémie.</li><li><strong>Organes</strong> : Insuffisance rénale chronique (IRC) avancée, insuffisance hépatique avancée.</li></ul>"},{"i":"217f86c861cb","n":105,"o":"105-6","u":"Etiologies","t":"Connaître les principales causes d'épilepsies","q":"Quelles sont les causes tumorales les plus fréquentes d'épilepsie chez l'adulte ?","a":"<p>Les tumeurs représentent environ 10% des épilepsies de l'adulte. On distingue :</p><ul><li><strong>Tumeurs de bas grade</strong> : Astrocytome, oligodendrogliome, méningiome.</li><li><strong>Tumeurs de haut grade</strong> : Glioblastome.</li><li><strong>Tumeurs secondaires</strong> : Métastase cérébrale.</li></ul><p>Les tumeurs à développement lent sont particulièrement épileptogènes.</p>"},{"i":"859f20b093d9","n":105,"o":"105-6","u":"Etiologies","t":"Connaître les principales causes d'épilepsies","q":"Comment différencier les crises symptomatiques aiguës des épilepsies vraies sur le plan nosologique ?","a":"<p>Il est impératif de distinguer les <strong>crises symptomatiques aiguës</strong> (ou provoquées), qui surviennent moins de 7 jours après une lésion cérébrale aiguë et ne constituent pas une épilepsie au sens propre, des <strong>épilepsies vraies</strong> (ou maladie épileptique) qui sont des maladies chroniques.</p>"},{"i":"a6c26a0152dd","n":105,"o":"105-6","u":"Etiologies","t":"Connaître les principales causes d'épilepsies","q":"Quelles sont les principales causes infectieuses de crises symptomatiques aiguës, en précisant les structures concernées ?","a":"<ul><li><strong>Méninges</strong> : Méningite, méningo-encéphalite (signe de gravité).</li><li><strong>Encéphale</strong> : Encéphalite herpétique (<strong>HSV</strong>).</li><li><strong>Collections</strong> : Abcès cérébral.</li></ul>"},{"i":"a719ba407b7c","n":105,"o":"105-6","u":"Etiologies","t":"Connaître les principales causes d'épilepsies","q":"Quelles sont les principales causes toxiques de crises symptomatiques aiguës ?","a":"<ul><li><strong>Alcool</strong> : Ivresse convulsivante, crise de sevrage (6 heures à 3 jours post-arrêt), épilepsie alcoolique.</li><li><strong>Médicaments</strong> : Surdosage (antidépresseurs tricycliques, neuroleptiques, <strong>lithium</strong>, <strong>isoniazide</strong>, théophylline, xylocaïne), sevrage (benzodiazépines, barbituriques).</li><li><strong>Drogues</strong> : Cocaïne.</li><li><strong>Toxique inhalé</strong> : Monoxyde de carbone.</li></ul>"},{"i":"af14d654913f","n":105,"o":"105-6","u":"Etiologies","t":"Connaître les principales causes d'épilepsies","q":"Citez les principales causes dysimmunes conduisant à l'épilepsie.","a":"<ul><li><strong>Auto-immunes non paranéoplasiques</strong> : Encéphalites à anticorps anti-NMDA-R, anti-LGI1, anti-CASPR2, neurolupus.</li><li><strong>Auto-immunes paranéoplasiques</strong> : Nécessitent la recherche d'un cancer sous-jacent (pulmonaire, ovarien, tératome...).</li></ul>"},{"i":"ce259ba2abf1","n":105,"o":"105-6","u":"Etiologies","t":"Connaître les principales causes d'épilepsies","q":"Quelles sont les principales causes vasculaires de crises symptomatiques aiguës ?","a":"<ul><li><strong>Accidents vasculaires cérébraux (AVC)</strong> : Ischémiques, hémorragiques, thrombophlébite cérébrale, hémorragie sous-arachnoïdienne (HSA – crises précoces ou épilepsie vasculaire séquellaire).</li><li><strong>Malformations vasculaires</strong> : Malformation artério-veineuse (MAV) non rompue, cavernome.</li><li><strong>Autres</strong> : Encéphalopathie hypertensive aiguë (PRES), angéite cérébrale.</li></ul>"},{"i":"f6b305ed2b2d","n":105,"o":"105-6","u":"Etiologies","t":"Connaître les principales causes d'épilepsies","q":"Quelles sont les principales causes d'épilepsie selon l'âge ?","a":"<ul><li><strong>Nouveau-né</strong> : Méningite bactérienne néonatale, anoxie périnatale, hypoglycémie, hypocalcémie, déficit en <strong>pyridoxine</strong> (Vitamine B6).</li><li><strong>Nourrisson &amp; jeune enfant</strong> : Convulsions fébriles, méningite bactérienne, hématome sous-dural (HSD) chronique, hypocalcémie, hypoglycémie, déshydratation.</li><li><strong>Adulte</strong> : Sevrage éthylique, tumoral (primitif ou métastase), vasculaire (AVC), séquelles post-traumatiques (post-TC, HSD chronique), <strong>sclérose hippocampique</strong> (épilepsie temporale interne).</li></ul>"},{"i":"0b2fa5781e78","n":105,"o":"105-8","u":"Diagnostic positif","t":"Connaître les diagnostics différentiels des crises d'épilepsie","q":"Quels sont les diagnostics différentiels d'une crise focale ?","a":"<p>Les diagnostics différentiels d'une crise focale sont :</p><ul><li>La <strong>migraine avec aura</strong> (aura migraineuse avec scotome scintillant, marche > <strong>5 minutes</strong>, suivie de céphalée).</li><li>Un événement <strong>vasculaire</strong>, tel qu'un Accident Ischémique Transitoire (AIT), présentant un déficit négatif sans marche des symptômes.</li><li>Un malaise <strong>hypoglycémique focal</strong>.</li><li>Une attaque de panique avec déréalisation, de cause <strong>psychiatrique</strong>.</li></ul>"},{"i":"1f5745a375b2","n":105,"o":"105-8","u":"Diagnostic positif","t":"Connaître les diagnostics différentiels des crises d'épilepsie","q":"Quels sont les diagnostics différentiels d'une absence ?","a":"<p>Les diagnostics différentiels d'une absence sont :</p><ul><li>L'<strong>inattention</strong> ou rêverie scolaire (interruptible par l'appel, pas d'arrêt brutal).</li><li>Un <strong>Tic</strong> ou un <strong>TOC</strong>.</li><li>Une <strong>crise focale avec rupture de contact</strong>, qui se caractérise par une durée plus longue, des automatismes et une phase post-critique présente.</li></ul>"},{"i":"447ae15d68fc","n":105,"o":"105-8","u":"Diagnostic positif","t":"Connaître les diagnostics différentiels des crises d'épilepsie","q":"Quels sont les diagnostics différentiels d'une crise généralisée tonico-clonique (CGTC) ?","a":"<p>Les diagnostics différentiels d'une CGTC sont :</p><ul><li>La <strong>syncope</strong>, qu'elle soit convulsive (avec myoclonies brèves) ou réflexe vagale (prodromes, pâleur, sueurs, récupération rapide sans confusion).</li><li>Les <strong>Crises Non Épileptiques Psychogènes (CNEP)</strong>, caractérisées par des mouvements anarchiques, une durée prolongée, des yeux fermés résistants à l'ouverture, et l'absence de phase post-critique.</li><li>L'<strong>hypoglycémie</strong>, en particulier dans un contexte de diabète, nécessitant une glycémie capillaire systématique.</li></ul>"},{"i":"d582c0f89b05","n":105,"o":"105-8","u":"Diagnostic positif","t":"Connaître les diagnostics différentiels des crises d'épilepsie","q":"Comment différencier une syncope convulsive d'une crise généralisée tonico-clonique (CGTC) ?","a":"<p>Pour différencier une syncope convulsive d'une CGTC, il faut rechercher :</p><ul><li>Des <strong>prodromes vagaux</strong> (pâleur, sueurs) avant la syncope.</li><li>Une durée des secousses < <strong>15 secondes</strong>.</li><li>L'absence de <strong>morsure latérale de la langue</strong>.</li><li>Une récupération < <strong>1 minute</strong> et sans confusion.</li></ul><p>Un <strong>ECG systématique</strong> est recommandé.</p>"},{"i":"1ff1702dace2","n":105,"o":"105-9","u":"Diagnostic positif","t":"Identifier des convulsions fébriles et leur pronostic selon les critères de gravité","q":"Quels sont les critères permettant de qualifier une convulsion fébrile de simple, et quel est son pronostic associé ?","a":"<p>Une convulsion fébrile est dite <strong>simple</strong> si elle répond à tous les critères suivants :</p><ul><li>Âge : <strong>≥ 1 an</strong>.</li><li>Crise : <strong>généralisée tonico-clonique</strong>.</li><li>Durée : <strong>< 15 minutes</strong>.</li><li>Unique : <strong>sur 24 heures</strong>.</li><li>Post-critique : récupération neurologique <strong>complète < 1 heure</strong>.</ul><p>Le pronostic d'une convulsion fébrile simple est <strong>excellent</strong>, avec un risque d'épilepsie ultérieure de l'ordre de <strong>1-2 %</strong>, proche de celui de la population générale.</p>"},{"i":"6128e8afdf9f","n":105,"o":"105-9","u":"Diagnostic positif","t":"Identifier des convulsions fébriles et leur pronostic selon les critères de gravité","q":"Quels sont les critères permettant de qualifier une convulsion fébrile de complexe, et quel est son pronostic associé ?","a":"<p>Une convulsion fébrile est dite <strong>complexe</strong> si elle présente au moins l'un des critères suivants :</p><ul><li>Âge : <strong>< 1 an</strong>.</li><li>Durée : <strong>> 15 minutes</strong>.</li><li>Crise : <strong>focale</strong> ou avec <strong>déficit post-critique</strong> (de Todd).</li><li>Répétée : <strong>dans les 24 heures</strong>.</li><li>Récupération neurologique : <strong>prolongée</strong>.</ul><p>Le pronostic d'une convulsion fébrile complexe est <strong>réservé</strong>, avec un risque d'épilepsie ultérieure de l'ordre de <strong>5-10 %</strong>.</p>"},{"i":"d0ce1fae41a7","n":105,"o":"105-9","u":"Diagnostic positif","t":"Identifier des convulsions fébriles et leur pronostic selon les critères de gravité","q":"Est-ce qu'une convulsion fébrile est considérée comme une épilepsie et nécessite un traitement antiépileptique de fond ?","a":"<p>Non, les convulsions fébriles <strong>ne sont pas une épilepsie</strong>. Ce sont des crises symptomatiques aiguës provoquées par la fièvre. Elles ne nécessitent <strong>pas de traitement antiépileptique de fond</strong>. L'information rassurante des parents et la mise en place d'un plan d'urgence (diazépam IR à domicile si CF prolongée connue) sont essentielles.</p>"},{"i":"d5328e5960c2","n":105,"o":"105-9","u":"Diagnostic positif","t":"Identifier des convulsions fébriles et leur pronostic selon les critères de gravité","q":"Quelle est la conduite à tenir en aigu devant une convulsion fébrile prolongée chez l'enfant ?","a":"<p>Si la crise dure <strong>> 5 minutes</strong>, il faut administrer :</p><ul><li><strong>Diazépam 0,5 mg/kg intra-rectal</strong> (maximum 10 mg) ;</li><li>Ou <strong>Midazolam buccal 0,3 mg/kg</strong>.</ul><p>Il est également recommandé d'administrer un <strong>antipyrétique</strong> (paracétamol 15 mg/kg) et de <strong>rechercher la cause de la fièvre</strong>.</p>"},{"i":"e9db95540054","n":105,"o":"105-9","u":"Diagnostic positif","t":"Identifier des convulsions fébriles et leur pronostic selon les critères de gravité","q":"Comment définir une convulsion fébrile chez l'enfant ?","a":"<p>Une convulsion fébrile est une crise épileptique survenant chez un enfant entre <strong>6 mois et 5 ans</strong>, dans le contexte d'une <strong>fièvre ≥ 38 °C</strong>, et en l'absence d'infection neuro-méningée ou d'autre cause neurologique identifiée.</p>"}]};